INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C1','kor',2,2,'u2',1,'고운 말의 뜻을 알고 상황에 맞게 주고받기 — 고운 말은 다른 사람의 마음을 헤아려서 부드럽게 하는 말임을 알고, 사랑해·고마워·넌 할 수 있어·수고했어처럼 축하·감사·칭찬·위로 상황에 알맞은 고운 말을 주고받기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C2','kor',2,2,'u2',1,'대화 속 인물의 기분 짐작하기 — 토끼와 거북, 하늘이와 친구들, 크니프와 속삭이처럼 대화 속 인물이 들은 말과 행동을 근거로 존중받지 못한 기분·존중받은 기분을 짐작하기',ARRAY['2국02-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C3','kor',2,2,'u2',3,'고운 말로 대화하는 방법 알기 — 욕설이나 비속어를 쓰지 않기, 상대의 기분이 상하지 않도록 말하기, 친구의 말을 잘 듣고 상황에 알맞은 말 하기, 상대의 말을 공감하며 들어 주기, 다른 의견도 고운 말로 말하기',ARRAY['2국01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C4','kor',2,2,'u2',5,'상황에 알맞은 고운 말로 대화하기 — 친구·가족·웃어른과 인사·놀이·헤어짐·다친 친구 돕기·약속에 늦음·휴대 전화 상황에서 누구와 어떤 상황인지 파악해 고운 말로 대화하고 역할놀이하기',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C5','kor',2,2,'u2',7,'칭찬과 조언의 뜻 구별하기 — 칭찬은 상대가 잘하는 점이나 노력하는 점, 좋은 점을 높이 평가해 주는 것, 조언은 다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것임을 알고 구별하기(「크니프의 친구 사귀기」)',ARRAY['2국01-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C6','kor',2,2,'u2',7,'바르게 칭찬하는 방법 — 열심히 노력하는 점을 찾아, 좋은 점을 너무 부풀리지 않고 진심으로, 칭찬하는 점과 그 까닭이 드러나게 칭찬하기(잘못한 점과 함께·부풀려서·까닭 없이 하는 칭찬 고치기)',ARRAY['2국01-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C7','kor',2,2,'u2',7,'바르게 조언하는 방법 — 걱정하는 마음을 담아 고치면 좋을 습관을 알려 주기, 문제를 해결할 수 있는 방법을 말하기, 듣는 사람의 마음에 공감하며 격려하기(비난·명령·성의 없음·무시하는 조언 고치기)',ARRAY['2국01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C8','kor',2,2,'u2',9,'말하는 사람에게 적절히 반응하기 — 말하는 사람을 쳐다보며 대화 내용에 집중하고, 끝까지 듣고 공감해 주며, 상황에 알맞은 표정을 짓고 부드러운 말투로 말하기, 말차례 지키기(비언어적·준언어적 반응)',ARRAY['2국01-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C9','kor',2,2,'u2',11,'소리가 같은 낱말 바르게 쓰기 — 안다/앉다, 짓다/짖다, 익다/읽다, 담다/닮다처럼 받침 소리는 같지만 철자와 뜻이 다른 낱말을 문장에 맞게 쓰기(기초 다지기)',ARRAY['2국04-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u2-C10','kor',2,2,'u2',11,'고운 말로 칭찬이나 조언을 실천하기 — 「칭찬합시다」·「조언을 구해요」 알림판 쪽지, 고운 말 사용 모범상, 칭찬이나 조언 책갈피처럼 생활 속에서 칭찬이나 조언을 내용·까닭이 드러나게, 책임감 있게 써서 전하기',ARRAY['2국01-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X01','kor',2,'u2',ARRAY['K2-2-u2-C1','K2-2-u2-C4']::text[],'고운 말을 상황과 맞지 않게 고른다(생일인 친구에게 「수고했어.」, 인사에 「축하해!」)','「지금 친구는 무엇을 했지? 무엇이 필요하지?」 — 축하·감사·칭찬·위로 네 칸 중 어디인지 먼저 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X02','kor',2,'u2',ARRAY['K2-2-u2-C1','K2-2-u2-C2','K2-2-u2-C4']::text[],'놀리는 말·거친 말(느림보·까불이·덜렁이·짜증 나·너 때문이야)을 장난이니 괜찮다고 여기거나 고운 말과 구별하지 못한다','그 말을 내가 들었다면 기분이 어떨지 얼굴 그림으로 골라 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X03','kor',2,'u2',ARRAY['K2-2-u2-C2']::text[],'대화나 이야기 속 인물이 들은 말·행동을 근거로 하지 않고 기분이나 고민을 엉뚱하게 짐작한다','「누가 무슨 말을 했지? 그 말을 들은 사람은?」 말 → 기분 순서로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X04','kor',2,'u2',ARRAY['K2-2-u2-C3','K2-2-u2-C4']::text[],'고운 말을 쓰는 것이 무조건 상대의 의견에 찬성하거나 다 들어주는 것이라고 여긴다','「다른 의견이 있을 때도 고운 말로 말할 수 있을까?」 — 「~하고 싶지만 …」 틀로 말해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X05','kor',2,'u2',ARRAY['K2-2-u2-C3']::text[],'고운 말로 대화하는 방법을 헷갈린다(기분 좋으면 무조건 크게, 내 상황만 생각, 친한 사이엔 비속어 괜찮다)','국어활동 26쪽 여섯 동물의 말을 하나씩 「상대의 기분은?」으로 따져 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X06','kor',2,'u2',ARRAY['K2-2-u2-C3','K2-2-u2-C8']::text[],'공감을 상대 말을 따라 하기·대충 맞장구로 여기거나, 「괜찮잖아」처럼 상대의 마음을 가볍게 넘긴다','「그 친구는 지금 어떤 마음일까?」를 먼저 말로 짚은 뒤(「걱정되겠다」) 대답하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X07','kor',2,'u2',ARRAY['K2-2-u2-C4']::text[],'웃어른(할머니·아빠)께 높임말 없이 말하거나, 가족이니 고운 말을 쓰지 않아도 된다고 여긴다','같은 말을 친구에게·할머니께 두 번 말해 보며 끝말(~요·~습니다)을 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X08','kor',2,'u2',ARRAY['K2-2-u2-C5']::text[],'칭찬과 조언을 구별하지 못한다(조언을 칭찬으로, 칭찬을 조언으로 고른다)','「좋은 점을 말했나, 어려움을 돕는 방법을 말했나?」 두 칸 중 하나에 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X09','kor',2,'u2',ARRAY['K2-2-u2-C6']::text[],'잘못한 점과 함께 하는 칭찬·너무 부풀린 칭찬·까닭 없는 칭찬도 바른 칭찬이라고 여긴다','들은 친구가 「왜?」, 「진짜?」 하고 갸웃하지 않을지 소리 내어 들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X10','kor',2,'u2',ARRAY['K2-2-u2-C6','K2-2-u2-C10']::text[],'노력·행동보다 결과·물건·외모만 칭찬하거나 칭찬을 보상(선물)과 이어 생각한다','「무엇을 했기에 칭찬하나?」 — 한 일(행동·노력)을 넣어 다시 칭찬하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X11','kor',2,'u2',ARRAY['K2-2-u2-C7','K2-2-u2-C10']::text[],'상대를 비난하며 명령하듯 하는 말(「넌 왜 그렇게 게으르니?」)도 조언이라고 여긴다','「~해!」를 「~하면 어떨까?」로 바꾸고, 상대를 꾸짖는 낱말 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X12','kor',2,'u2',ARRAY['K2-2-u2-C7']::text[],'해결 방법 없이 성의 없게 하는 말(「그냥 하면 돼.」)을 조언이라고 여긴다','「그래서 무엇을, 어떻게 하면 돼?」 — 방법 한 가지를 꼭 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X13','kor',2,'u2',ARRAY['K2-2-u2-C7']::text[],'상대의 고민을 무시하듯 하는 말(「뭐 그런 일로 고민해?」)도 괜찮다고 여긴다','고민을 말한 친구의 마음을 먼저 말해 주기 — 「속상했구나.」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X14','kor',2,'u2',ARRAY['K2-2-u2-C8']::text[],'반응할 때 말의 내용만 중요하다고 여겨 시선·표정·말투를 놓치거나, 딴짓하며 건성으로 듣는다','짝과 「혼자 말해요」 놀이로 딴짓할 때·바라볼 때 기분을 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X15','kor',2,'u2',ARRAY['K2-2-u2-C8']::text[],'말을 끊고 끼어들거나 말차례를 지키지 않고, 무조건 크게·많이 반응하면 좋다고 여긴다','친구 말이 끝났다는 신호(말끝·눈 맞춤)를 기다린 뒤 한 번 고개를 끄덕이고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X16','kor',2,'u2',ARRAY['K2-2-u2-C9']::text[],'소리가 같은 낱말의 철자를 헷갈린다(안다/앉다, 짓다/짖다, 익다/읽다, 담다/닮다)','낱말을 「~아요」로 바꿔 읽어 보기 — 앉아요·짖어요·읽어요·닮아요에서 숨은 받침이 들려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u2-X17','kor',2,'u2',ARRAY['K2-2-u2-C10']::text[],'칭찬·조언 쪽지나 상장에 내용·까닭을 빼거나, 이름을 밝히지 않고 장난스럽게 쓰거나, 활동과 상관없는 것을 쓴다','쪽지를 붙이기 전에 「누구에게 · 무엇을 · 왜」 세 가지가 있는지 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#1','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 41쪽 생각 열기 — 「느림보」, 「까불이」라는 말을 들은 토끼와 거북의 기분은 어떠할까요?',ARRAY['K2-2-u2-X03','K2-2-u2-X02']::text[],false,'{"seq":1,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 41쪽 생각 열기 — 「느림보」, 「까불이」라는 말을 들은 토끼와 거북의 기분은 어떠할까요?","options":[{"t":"존중받지 못해서 기분이 나빠요","correct":true},{"t":"칭찬을 받아서 기분이 좋아요","mis":"K2-2-u2-X03"},{"t":"장난이라서 아무렇지 않아요","mis":"K2-2-u2-X02"}],"explanation":["놀리는 말을 들었어요.","존중받지 못하면 기분이 상해요.","41쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"토끼","text":"이 느림보 거북아, 넌 느려서 정말 답답해!"},{"who":"거북","text":"이 까불이 토끼야! 촐랑대는 너를 보면 정말 짜증 나!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#2','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 41쪽 — 「노력하는 네 모습은 정말 대단해!」를 들은 거북의 기분은 어떠할까요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 41쪽 — 「노력하는 네 모습은 정말 대단해!」를 들은 거북의 기분은 어떠할까요?","options":[{"t":"칭찬을 받아서 기분이 좋아요","correct":true},{"t":"놀림을 받아서 속상해요","mis":"K2-2-u2-X03"},{"t":"화가 나요","mis":"K2-2-u2-X03"}],"explanation":["노력을 알아봐 주었어요.","그래서 기분이 좋아요.","41쪽 뒤 그림이에요."],"asset":{"type":"speech","turns":[{"who":"토끼","text":"거북아, 빠르게 달리려고 노력하는 네 모습은 정말 대단해!"},{"who":"거북","text":"고마워, 토끼야. 너는 정말 달리기를 잘하더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#3','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',1,'mc','auto','『국어』 43쪽 — 고운 말은 어떤 말인가요?',ARRAY['K2-2-u2-X05','K2-2-u2-X01']::text[],false,'{"seq":3,"concept":"K2-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어』 43쪽 — 고운 말은 어떤 말인가요?","options":[{"t":"다른 사람의 마음을 헤아려서 부드럽게 하는 말","correct":true},{"t":"다른 사람보다 큰 소리로 하는 말","mis":"K2-2-u2-X05"},{"t":"어려운 낱말을 많이 쓴 말","mis":"K2-2-u2-X01"}],"explanation":["마음을 헤아려요.","부드럽게 말해요.","43쪽 도움말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#4','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',1,'mc','auto','노래 「꽃같이 예쁜 말」에 나오는 고운 말로 알맞은 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":4,"concept":"K2-2-u2-C1","difficulty":1,"kind":"mc","stem":"노래 「꽃같이 예쁜 말」에 나오는 고운 말로 알맞은 것은?","options":[{"t":"고마워","correct":true},{"t":"저리 가","mis":"K2-2-u2-X02"},{"t":"몰라","mis":"K2-2-u2-X02"}],"explanation":["「고마워」는 고운 말이에요.","사랑해·수고했어도 있어요.","지도서 97쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#5','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',2,'match','auto','『국어』 43쪽 2번 — 먼저 한 말과 대답하는 고운 말을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K2-2-u2-C1","difficulty":2,"kind":"match","stem":"『국어』 43쪽 2번 — 먼저 한 말과 대답하는 고운 말을 이어 보세요.","pairs":[{"l":"상 받았구나. 축하해!","r":"네가 축하해 주니 기분이 좋아."},{"l":"어디 아프니?","r":"감기에 걸린 것 같아. 걱정해 줘서 고마워."},{"l":"실수로 네 물건을 떨어뜨려서 미안해.","r":"괜찮아. 일부러 그런 것 아니잖아."}],"mis":"K2-2-u2-X01","explanation":["축하에는 고마움으로 대답해요.","걱정에는 고마움, 사과에는 괜찮다고 해요.","43쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#6','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',2,'mc','auto','심부름을 다녀온 동생에게 하는 고운 말로 알맞은 것은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":6,"concept":"K2-2-u2-C1","difficulty":2,"kind":"mc","stem":"심부름을 다녀온 동생에게 하는 고운 말로 알맞은 것은?","options":[{"t":"수고했어.","correct":true},{"t":"생일 축하해!","mis":"K2-2-u2-X01"},{"t":"일부러 그런 것 아니잖아.","mis":"K2-2-u2-X01"}],"explanation":["애쓴 일에는 「수고했어.」","상황에 맞는 고운 말을 골라요.","지도서 97쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#7','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',2,'mc','auto','『국어』 43쪽 — 「노래를 잘 부르는 네가 부러워.」에 대답하는 고운 말로 알맞은 것은?',ARRAY['K2-2-u2-X02','K2-2-u2-X01']::text[],false,'{"seq":7,"concept":"K2-2-u2-C1","difficulty":2,"kind":"mc","stem":"『국어』 43쪽 — 「노래를 잘 부르는 네가 부러워.」에 대답하는 고운 말로 알맞은 것은?","options":[{"t":"칭찬 고마워. 나는 달리기를 잘하는 네가 부러워.","correct":true},{"t":"당연하지, 너는 노래를 못하잖아.","mis":"K2-2-u2-X02"},{"t":"그런 말 하지 마.","mis":"K2-2-u2-X01"}],"explanation":["고마움을 나타냈어요.","상대의 좋은 점도 말해 주었어요.","43쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#8','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',2,'ox','auto','서로 고운 말을 주고받으면 기분 좋게 대화할 수 있어요.',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":8,"concept":"K2-2-u2-C1","difficulty":2,"kind":"ox","stem":"서로 고운 말을 주고받으면 기분 좋게 대화할 수 있어요.","answer":"O","reason_options":[{"t":"고운 말은 상대의 마음을 헤아린 말이라 듣는 사람의 기분이 좋아지니까","correct":true},{"t":"고운 말을 쓰면 대화를 빨리 끝낼 수 있으니까","mis":"K2-2-u2-X05"}],"mis":"K2-2-u2-X05","explanation":["고운 말은 마음을 헤아려요.","그래서 서로 기분이 좋아요.","지도서 97쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#9','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C2',2,'mc','auto','『국어』 43쪽 3번 — 친구와 고운 말로 대화하고 든 생각이나 느낌으로 알맞은 것은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":9,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 43쪽 3번 — 친구와 고운 말로 대화하고 든 생각이나 느낌으로 알맞은 것은?","options":[{"t":"고운 말을 해 준 친구와 더 친하게 지내고 싶어졌어","correct":true},{"t":"친구에게 다시는 말하고 싶지 않아","mis":"K2-2-u2-X03"},{"t":"아무 생각도 들지 않아","mis":"K2-2-u2-X03"}],"explanation":["고운 말은 가깝게 해 줘요.","43쪽 말풍선이에요.","느낌을 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_basic#10','kor',2,2,'u2','L01','g2_2_kor_u2_L01_basic','lesson_basic','K2-2-u2-C1',3,'mc','auto','거북이 「이 까불이 토끼야!」 대신 할 수 있는 고운 말로 알맞은 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":10,"concept":"K2-2-u2-C1","difficulty":3,"kind":"mc","stem":"거북이 「이 까불이 토끼야!」 대신 할 수 있는 고운 말로 알맞은 것은?","options":[{"t":"고마워, 토끼야. 너는 정말 달리기를 잘하더라.","correct":true},{"t":"촐랑대는 너를 보면 정말 짜증 나!","mis":"K2-2-u2-X02"},{"t":"됐거든, 저리 가.","mis":"K2-2-u2-X02"}],"explanation":["좋은 점을 말해 주었어요.","놀리는 말을 고운 말로 바꿨어요.","41쪽 뒤 그림이에요."],"asset":{"type":"speech","turns":[{"who":"토끼","text":"이 느림보 거북아, 넌 느려서 정말 답답해!"},{"who":"거북","text":"이 까불이 토끼야! 촐랑대는 너를 보면 정말 짜증 나!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
