INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#4','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C1',3,'mc','auto','고운 말을 상황에 알맞지 않게 쓴 것은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":4,"concept":"K2-2-u2-C1","difficulty":3,"kind":"mc","stem":"고운 말을 상황에 알맞지 않게 쓴 것은?","options":[{"t":"생일인 친구에게 「수고했어.」","correct":true},{"t":"줄넘기를 연습하는 친구에게 「넌 할 수 있어.」","mis":"K2-2-u2-X01"},{"t":"선물을 받고 「고마워.」","mis":"K2-2-u2-X01"}],"explanation":["생일에는 축하하는 말이 어울려요.","고운 말도 상황에 맞아야 해요.","지도서 95쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#5','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C2',3,'mc','auto','『국어』 41쪽 뒤 그림에서 토끼와 거북이 둘 다 기분이 좋아진 까닭은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":5,"concept":"K2-2-u2-C2","difficulty":3,"kind":"mc","stem":"『국어』 41쪽 뒤 그림에서 토끼와 거북이 둘 다 기분이 좋아진 까닭은?","options":[{"t":"서로 잘하는 점을 찾아 고운 말로 말해 주었기 때문이에요","correct":true},{"t":"달리기 시합을 하지 않았기 때문이에요","mis":"K2-2-u2-X03"},{"t":"둘 다 목소리가 컸기 때문이에요","mis":"K2-2-u2-X03"}],"explanation":["노력하는 점·잘하는 점을 말했어요.","존중하는 말이에요.","41쪽이에요."],"asset":{"type":"speech","turns":[{"who":"토끼","text":"거북아, 빠르게 달리려고 노력하는 네 모습은 정말 대단해!"},{"who":"거북","text":"고마워, 토끼야. 너는 정말 달리기를 잘하더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#6','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C1',3,'mc','auto','다른 사람과 고운 말을 주고받을 때 먼저 할 일은?',ARRAY['K2-2-u2-X05','K2-2-u2-X15']::text[],false,'{"seq":6,"concept":"K2-2-u2-C1","difficulty":3,"kind":"mc","stem":"다른 사람과 고운 말을 주고받을 때 먼저 할 일은?","options":[{"t":"상대의 말을 잘 듣고 상황을 살펴요","correct":true},{"t":"생각나는 말을 바로 크게 말해요","mis":"K2-2-u2-X05"},{"t":"상대의 말이 끝나기 전에 대답해요","mis":"K2-2-u2-X15"}],"explanation":["잘 들어야 알맞은 말을 해요.","상황을 먼저 살펴요.","지도서 97쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#7','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C2',3,'error','auto','한 친구가 「느림보라고 불러도 장난이니까 괜찮아.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X02','K2-2-u2-X03']::text[],false,'{"seq":7,"concept":"K2-2-u2-C2","difficulty":3,"kind":"error","stem":"한 친구가 「느림보라고 불러도 장난이니까 괜찮아.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"장난이라도 듣는 사람은 존중받지 못해 기분이 상해요","correct":true,"mis_target":"K2-2-u2-X02"},{"t":"잘 말했어요","mis":"K2-2-u2-X02"},{"t":"「거북이」라고 불러야 해요","mis":"K2-2-u2-X03"}],"explanation":["듣는 사람의 기분이 중요해요.","장난도 상처가 돼요.","41쪽 생각 열기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#8','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C1',4,'sa','auto','「다른 사람의 마음을 헤아려서 부드럽게 하는 말」을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C1","difficulty":4,"kind":"sa","stem":"「다른 사람의 마음을 헤아려서 부드럽게 하는 말」을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["고운 말","고운말"],"explanation":["고운 말이에요.","43쪽 도움말이에요.","마음을 헤아려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#9','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C1',4,'essay','teacher','『국어』 43쪽 2번처럼 친구에게 하고 싶은 고운 말과, 그 말을 들은 친구가 할 대답을 고운 말로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C1","difficulty":4,"kind":"essay","stem":"『국어』 43쪽 2번처럼 친구에게 하고 싶은 고운 말과, 그 말을 들은 친구가 할 대답을 고운 말로 쓰세요.","answer_guide":{"answer":"예: 「상 받았구나. 축하해!」 — 「네가 축하해 주니 기분이 좋아.」 — 두 말이 모두 상대의 마음을 헤아린 고운 말이면 맞아요.","scoring_points":["고운 말로 먼저 하는 말이 있어요","상황에 어울리는 고운 대답이 있어요"]},"explanation":["먼저 하는 말을 써요.","고운 말로 대답해요.","43쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L01_challenge#10','kor',2,2,'u2','L01','g2_2_kor_u2_L01_challenge','lesson_challenge','K2-2-u2-C1',4,'essay','teacher','노래 「꽃같이 예쁜 말」에 나오는 고운 말 하나를 골라, 누구에게 왜 말하고 싶은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u2-C1","difficulty":4,"kind":"essay","stem":"노래 「꽃같이 예쁜 말」에 나오는 고운 말 하나를 골라, 누구에게 왜 말하고 싶은지 쓰세요.","answer_guide":{"answer":"예: 줄넘기 연습을 하는 친구에게 「넌 할 수 있어.」라고 말하고 싶어요. 친구가 힘을 냈으면 좋겠어요.","scoring_points":["노래에 나오는 고운 말을 골랐어요","누구에게 말할지 썼어요","까닭이 있어요"]},"explanation":["누구에게 말할지 정해요.","까닭을 함께 써요.","42쪽 (2)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#1','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 45쪽 2번 (1) — 하늘이와 친구들의 대화는 언제 있었던 일인가요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":1,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 45쪽 2번 (1) — 하늘이와 친구들의 대화는 언제 있었던 일인가요?","options":[{"t":"쉬는 시간","correct":true},{"t":"점심 먹는 시간","mis":"K2-2-u2-X03"},{"t":"집에 가는 길","mis":"K2-2-u2-X03"}],"explanation":["쉬는 시간이에요.","「쉬는 시간이다!」를 찾아요.","45쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#2','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 44쪽 — 하늘이가 친구들에게 같이 하자고 한 놀이는?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 44쪽 — 하늘이가 친구들에게 같이 하자고 한 놀이는?","options":[{"t":"쌓기 놀이","correct":true},{"t":"보드게임","mis":"K2-2-u2-X03"},{"t":"술래잡기","mis":"K2-2-u2-X03"}],"explanation":["쌓기 놀이예요.","보드게임은 정현이가 하고 싶은 놀이예요.","44쪽이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#3','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C3',1,'mc','auto','『국어활동』 26쪽 — 고운 말로 대화하는 방법으로 알맞은 것은?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":3,"concept":"K2-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어활동』 26쪽 — 고운 말로 대화하는 방법으로 알맞은 것은?","options":[{"t":"욕설이나 비속어를 사용하지 않아요","correct":true},{"t":"기분이 좋으면 무조건 크게 말해요","mis":"K2-2-u2-X05"},{"t":"말하는 사람의 상황만 생각해요","mis":"K2-2-u2-X05"}],"explanation":["욕설·비속어를 쓰지 않아요.","47쪽 정리예요.","국어활동 26쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#4','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C3',1,'mc','auto','『국어』 46쪽 — 「공감」은 무엇인가요?',ARRAY['K2-2-u2-X04','K2-2-u2-X06']::text[],false,'{"seq":4,"concept":"K2-2-u2-C3","difficulty":1,"kind":"mc","stem":"『국어』 46쪽 — 「공감」은 무엇인가요?","options":[{"t":"다른 사람의 생각과 마음에 대하여 자신도 그렇게 느끼는 것","correct":true},{"t":"상대의 말에 무조건 찬성하는 것","mis":"K2-2-u2-X04"},{"t":"상대의 말을 그대로 따라 하는 것","mis":"K2-2-u2-X06"}],"explanation":["나도 그렇게 느끼는 것이에요.","46쪽 도움말이에요.","마음을 같이 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#5','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C2',2,'mc','auto','『국어』 45쪽 2번 (2) — 장면 ①~②처럼 민서와 대화했을 때 하늘이의 기분은 어땠을까요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":5,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 2번 (2) — 장면 ①~②처럼 민서와 대화했을 때 하늘이의 기분은 어땠을까요?","options":[{"t":"민서가 말을 잘 듣고 공감해 주어 기분이 좋았을 것 같아요","correct":true},{"t":"민서가 짜증을 내서 속상했을 것 같아요","mis":"K2-2-u2-X03"},{"t":"민서가 대답하지 않아서 서운했을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["「좋은 생각이야.」 했어요.","공감해 주었어요.","45쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#6','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C2',2,'mc','auto','『국어』 45쪽 2번 (3) — 장면 ③에서 정현이의 말을 들었을 때 하늘이의 기분은 어땠을까요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":6,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 2번 (3) — 장면 ③에서 정현이의 말을 들었을 때 하늘이의 기분은 어땠을까요?","options":[{"t":"정현이가 짜증을 내며 말해 당황스러웠을 것 같아요","correct":true},{"t":"칭찬을 받아 뿌듯했을 것 같아요","mis":"K2-2-u2-X03"},{"t":"함께 놀게 되어 신났을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["「짜증 나!」라고 했어요.","그래서 당황했을 거예요.","45쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#7','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C2',2,'mc','auto','『국어』 45쪽 2번 (4) — 장면 ④처럼 하영이와 대화했을 때 하늘이의 기분은 어땠을까요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":7,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 2번 (4) — 장면 ④처럼 하영이와 대화했을 때 하늘이의 기분은 어땠을까요?","options":[{"t":"자신의 말을 집중해 듣지 않아서 기분이 나빴을 것 같아요","correct":true},{"t":"하영이가 공감해 주어 기뻤을 것 같아요","mis":"K2-2-u2-X03"},{"t":"하영이가 칭찬해 주어 고마웠을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["「어……. 뭐가?」라고 했어요.","듣지 않았다는 뜻이에요.","45쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#8','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C3',2,'match','auto','『국어』 46쪽 4번 — 대화 속 말과 고운 말로 대화하는 방법을 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C3","difficulty":2,"kind":"match","stem":"『국어』 46쪽 4번 — 대화 속 말과 고운 말로 대화하는 방법을 이어 보세요.","pairs":[{"l":"기분이 안 좋아 보인다. 어디 아프니?","r":"상대의 기분을 살펴 말한다"},{"l":"가위가 없어서 깜짝 놀랐겠다. 오늘 나랑 같이 사용하자.","r":"상대의 말을 공감하며 들어 준다"}],"mis":"K2-2-u2-X06","explanation":["기분을 살펴 물었어요.","놀랐을 마음을 알아주었어요.","46쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#9','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C4',2,'ox','auto','고운 말을 쓴다는 것은 무조건 친구의 의견에 찬성하는 거예요.',ARRAY['K2-2-u2-X04']::text[],false,'{"seq":9,"concept":"K2-2-u2-C4","difficulty":2,"kind":"ox","stem":"고운 말을 쓴다는 것은 무조건 친구의 의견에 찬성하는 거예요.","answer":"X","reason_options":[{"t":"다른 의견이 있어도 상대의 기분이 상하지 않게 내 생각을 말할 수 있으니까","correct":true},{"t":"친구와 다른 의견은 말하면 안 되니까","mis":"K2-2-u2-X04"}],"mis":"K2-2-u2-X04","explanation":["찬성만이 고운 말이 아니에요.","다른 의견도 고운 말로 말해요.","지도서 101쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_basic#10','kor',2,2,'u2','L03','g2_2_kor_u2_L03_basic','lesson_basic','K2-2-u2-C4',3,'mc','auto','『국어』 45쪽 3번 — 정현이가 고운 말로 말하려면 어떻게 바꾸면 좋을까요?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어』 45쪽 3번 — 정현이가 고운 말로 말하려면 어떻게 바꾸면 좋을까요?","options":[{"t":"나는 보드게임이 하고 싶지만 지금은 네 의견을 따를게. 다음 쉬는 시간에는 보드게임하자!","correct":true},{"t":"됐어, 너희끼리 해.","mis":"K2-2-u2-X02"},{"t":"쌓기 놀이는 시시해.","mis":"K2-2-u2-X02"}],"explanation":["내 생각을 말했어요.","하늘이의 기분도 살폈어요.","45쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#1','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',2,'mc','auto','『국어』 47쪽 — 「비속어」는 어떤 말인가요?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":1,"concept":"K2-2-u2-C3","difficulty":2,"kind":"mc","stem":"『국어』 47쪽 — 「비속어」는 어떤 말인가요?","options":[{"t":"예절에 어긋나게 대상을 낮추어 보거나 하찮게 여기는 말","correct":true},{"t":"웃어른께 쓰는 높임말","mis":"K2-2-u2-X05"},{"t":"소리나 모양을 흉내 내는 말","mis":"K2-2-u2-X05"}],"explanation":["대상을 낮추어 보는 말이에요.","47쪽 도움말이에요.","쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#2','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',2,'mc','auto','『국어』 45쪽 도움말 — 하영이가 고쳐야 할 점은?',ARRAY['K2-2-u2-X05','K2-2-u2-X04']::text[],false,'{"seq":2,"concept":"K2-2-u2-C3","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 도움말 — 하영이가 고쳐야 할 점은?","options":[{"t":"하늘이가 하는 말을 귀담아들어야 해요","correct":true},{"t":"더 큰 소리로 말해야 해요","mis":"K2-2-u2-X05"},{"t":"보드게임을 하자고 해야 해요","mis":"K2-2-u2-X04"}],"explanation":["귀담아들어야 해요.","45쪽 도움말이에요.","잘 들어야 대답해요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#3','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',3,'error','auto','『국어활동』 26쪽 — 고운 말로 대화하는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#4','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',3,'error','auto','한 친구가 「대화할 때는 내 상황만 생각해서 말하면 돼.」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":4,"concept":"K2-2-u2-C3","difficulty":3,"kind":"error","stem":"한 친구가 「대화할 때는 내 상황만 생각해서 말하면 돼.」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"상대의 기분과 상황도 살펴 말해야 해요","correct":true,"mis_target":"K2-2-u2-X05"},{"t":"잘 말했어요","mis":"K2-2-u2-X05"},{"t":"더 크게 말해야 해요","mis":"K2-2-u2-X05"}],"explanation":["상대의 기분을 살펴요.","상황에 알맞게 말해요.","국어활동 26쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#5','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',3,'mc','auto','『국어』 46쪽 가 — 「어제부터 머리가 좀 아파. 걱정해 줘서 고마워.」에 쓰인 방법은?',ARRAY['K2-2-u2-X06','K2-2-u2-X03']::text[],false,'{"seq":5,"concept":"K2-2-u2-C3","difficulty":3,"kind":"mc","stem":"『국어』 46쪽 가 — 「어제부터 머리가 좀 아파. 걱정해 줘서 고마워.」에 쓰인 방법은?","options":[{"t":"자신의 기분을 살펴 준 것에 고마움을 나타낸다","correct":true},{"t":"상대의 말을 공감하며 들어 준다","mis":"K2-2-u2-X06"},{"t":"자신의 상황을 이해할 수 있게 설명한다","mis":"K2-2-u2-X03"}],"explanation":["「걱정해 줘서 고마워.」","고마움을 나타냈어요.","46쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"기분이 안 좋아 보인다. 어디 아프니?"},{"who":"친구 2","text":"어제부터 머리가 좀 아파. 걱정해 줘서 고마워."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#6','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',3,'mc','auto','『국어』 46쪽 나 — 「가위를 깜빡 잊고 가져오지 못했어. 네 가위 좀 빌려줄래?」에 쓰인 방법은?',ARRAY['K2-2-u2-X05','K2-2-u2-X06']::text[],false,'{"seq":6,"concept":"K2-2-u2-C3","difficulty":3,"kind":"mc","stem":"『국어』 46쪽 나 — 「가위를 깜빡 잊고 가져오지 못했어. 네 가위 좀 빌려줄래?」에 쓰인 방법은?","options":[{"t":"자신의 상황을 이해할 수 있게 설명한다","correct":true},{"t":"상대의 기분을 살펴 말한다","mis":"K2-2-u2-X05"},{"t":"자신의 기분을 살펴 준 것에 고마움을 나타낸다","mis":"K2-2-u2-X06"}],"explanation":["왜 빌리는지 말했어요.","상황을 설명했어요.","46쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"가위를 깜빡 잊고 가져오지 못했어. 네 가위 좀 빌려줄래?"},{"who":"친구 2","text":"가위가 없어서 깜짝 놀랐겠다. 오늘 나랑 같이 사용하자. 여기 있어!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#7','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C4',3,'mc','auto','『국어』 47쪽 5번 가 — 복도에서 친구와 부딪혔더니 친구가 「앗, 깜짝이야!」 했어요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02','K2-2-u2-X05']::text[],false,'{"seq":7,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어』 47쪽 5번 가 — 복도에서 친구와 부딪혔더니 친구가 「앗, 깜짝이야!」 했어요. 알맞은 고운 말은?","options":[{"t":"다치지 않았니? 내가 급하게 가느라 못 봤어. 미안해.","correct":true},{"t":"네가 앞을 안 봐서 그렇잖아!","mis":"K2-2-u2-X02"},{"t":"나는 안 다쳤으니까 됐어.","mis":"K2-2-u2-X05"}],"explanation":["먼저 친구를 걱정해요.","미안한 마음을 말해요.","47쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#8','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',4,'sa','auto','「다른 사람의 생각과 마음에 대하여 자신도 그렇게 느끼는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C3","difficulty":4,"kind":"sa","stem":"「다른 사람의 생각과 마음에 대하여 자신도 그렇게 느끼는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["공감"],"explanation":["공감이에요.","46쪽 도움말이에요.","마음을 같이 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#9','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C3',4,'essay','teacher','『국어』 47쪽 5번 나 — 「난 그림 그리기를 좋아해.」 하는 친구에게 고운 말로 대답하는 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C3","difficulty":4,"kind":"essay","stem":"『국어』 47쪽 5번 나 — 「난 그림 그리기를 좋아해.」 하는 친구에게 고운 말로 대답하는 말을 쓰세요.","answer_guide":{"answer":"예: 내가 그림 그리기를 좋아해서 그런지 네 그림을 보면 기분이 좋아져.","scoring_points":["친구의 말을 잘 듣고 대답했어요","상대의 기분이 좋아지는 고운 말이에요"]},"explanation":["친구의 말을 잘 들어요.","고운 말로 대답해요.","47쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L03_challenge#10','kor',2,2,'u2','L03','g2_2_kor_u2_L03_challenge','lesson_challenge','K2-2-u2-C4',4,'essay','teacher','하늘이가 「쌓기 놀이 같이 하는 거 어때?」라고 했어요. 내가 다른 놀이를 하고 싶다면 하늘이의 기분이 상하지 않게 어떻게 말할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"하늘이가 「쌓기 놀이 같이 하는 거 어때?」라고 했어요. 내가 다른 놀이를 하고 싶다면 하늘이의 기분이 상하지 않게 어떻게 말할지 쓰세요.","answer_guide":{"answer":"예: 좋은 생각이야. 나는 술래잡기도 하고 싶은데, 이번에는 쌓기 놀이를 하고 다음 쉬는 시간에 술래잡기하자.","scoring_points":["내 생각을 말했어요","상대의 기분이 상하지 않는 고운 말이에요"]},"explanation":["다른 의견도 말할 수 있어요.","고운 말로 말해요.","지도서 101쪽이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#1','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',1,'mc','auto','『국어』 48쪽 그림 다는 누구와 누구의 대화인가요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":1,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 48쪽 그림 다는 누구와 누구의 대화인가요?","options":[{"t":"할머니와 손자","correct":true},{"t":"친구와 친구","mis":"K2-2-u2-X03"},{"t":"아빠와 딸","mis":"K2-2-u2-X03"}],"explanation":["할머니와 손자예요.","48쪽 (1) 예시 답안이에요.","그림을 살펴요."],"asset":{"type":"passage","lines":["가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」","나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」","다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」"],"title":"『국어』 48쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#2','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',1,'mc','auto','『국어』 48쪽 그림 가는 어떤 상황인가요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 48쪽 그림 가는 어떤 상황인가요?","options":[{"t":"국어 시간에 누가 발표를 할지 이야기하는 상황","correct":true},{"t":"생일 선물을 주는 상황","mis":"K2-2-u2-X03"},{"t":"함께 장난감으로 노는 상황","mis":"K2-2-u2-X03"}],"explanation":["발표 차례를 정해요.","48쪽 (2) 예시 답안이에요.","말풍선을 읽어요."],"asset":{"type":"passage","lines":["가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」","나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」","다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」"],"title":"『국어』 48쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#3','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',1,'mc','auto','『국어』 49쪽 — 「학교 다녀오겠습니다.」에 대답하는 고운 말은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":3,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 49쪽 — 「학교 다녀오겠습니다.」에 대답하는 고운 말은?","options":[{"t":"조심히 다녀오렴.","correct":true},{"t":"점심시간에 나랑 축구할래?","mis":"K2-2-u2-X01"},{"t":"그동안 고마웠어.","mis":"K2-2-u2-X01"}],"explanation":["「조심히 다녀오렴.」","인사에 어울리는 대답이에요.","49쪽 그림 가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#4','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',1,'mc','auto','『국어』 49쪽 — 전학 가는 친구가 「잘 있어. 그동안 고마웠어.」 했어요. 알맞은 대답은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":4,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 49쪽 — 전학 가는 친구가 「잘 있어. 그동안 고마웠어.」 했어요. 알맞은 대답은?","options":[{"t":"너와 헤어져서 아쉬워. 앞으로 자주 연락하자.","correct":true},{"t":"좋아! 오늘도 재미있게 놀자.","mis":"K2-2-u2-X01"},{"t":"조심히 다녀오렴.","mis":"K2-2-u2-X01"}],"explanation":["헤어지는 상황이에요.","아쉬운 마음을 말해요.","49쪽 그림 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#5','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',2,'mc','auto','『국어』 48쪽 — 손자가 할머니께 「제 생일을 축하해 주셔서 고맙습니다.」라고 했어요. 웃어른께 고운 말을 할 때 알맞은 것은?',ARRAY['K2-2-u2-X07']::text[],false,'{"seq":5,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 48쪽 — 손자가 할머니께 「제 생일을 축하해 주셔서 고맙습니다.」라고 했어요. 웃어른께 고운 말을 할 때 알맞은 것은?","options":[{"t":"높임말로 고마움을 나타내요","correct":true},{"t":"친구에게 하듯 반말로 말해요","mis":"K2-2-u2-X07"},{"t":"부끄러우니까 아무 말도 하지 않아요","mis":"K2-2-u2-X07"}],"explanation":["웃어른께는 높임말이에요.","고마움을 나타내요.","48쪽 그림 다예요."],"asset":{"type":"passage","lines":["가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」","나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」","다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」"],"title":"『국어』 48쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#6','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',2,'mc','auto','『국어』 50쪽 가 — 다리를 다친 친구가 「운동장에 나가고 싶어.」라고 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":6,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 50쪽 가 — 다리를 다친 친구가 「운동장에 나가고 싶어.」라고 해요. 알맞은 고운 말은?","options":[{"t":"다리를 다쳐서 힘들지? 내가 문을 열어 줄게.","correct":true},{"t":"다리도 아픈데 왜 나가?","mis":"K2-2-u2-X02"},{"t":"혼자 알아서 해.","mis":"K2-2-u2-X02"}],"explanation":["친구의 처지를 헤아려요.","도와주는 말을 해요.","지도서 107쪽 대본이에요."],"asset":{"type":"scene","icon":"🩼🚪🧒","text":"『국어』 50쪽 그림 가 — 다리를 다쳐 목발을 짚은 친구가 운동장에 나가고 싶어 해요. 문을 여닫기가 불편해요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#7','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',2,'mc','auto','『국어』 50쪽 나 — 늦게 온 친구가 「승훈아, 내가 늦었지?」라고 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02','K2-2-u2-X04']::text[],false,'{"seq":7,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 50쪽 나 — 늦게 온 친구가 「승훈아, 내가 늦었지?」라고 해요. 알맞은 고운 말은?","options":[{"t":"기다리느라 힘들었어. 다음부터는 좀 일찍 오면 좋겠어.","correct":true},{"t":"너랑 다시는 안 놀아!","mis":"K2-2-u2-X02"},{"t":"괜찮아, 다음에도 늦어도 돼.","mis":"K2-2-u2-X04"}],"explanation":["내 마음을 솔직하게 말해요.","기분이 상하지 않게 바라는 점을 말해요.","50쪽 예시 답안이에요."],"asset":{"type":"scene","icon":"⏰🧒🧒","text":"『국어』 50쪽 그림 나 — 친구가 약속 시간을 지키지 못하고 늦게 와서 승훈이가 한참을 기다렸어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#8','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',2,'mc','auto','『국어』 50쪽 다 — 아빠께서 「아직도 휴대 전화를 하고 있네.」 하셨어요. 알맞은 대답은?',ARRAY['K2-2-u2-X07','K2-2-u2-X14']::text[],false,'{"seq":8,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 50쪽 다 — 아빠께서 「아직도 휴대 전화를 하고 있네.」 하셨어요. 알맞은 대답은?","options":[{"t":"아빠, 제가 휴대 전화를 너무 오랫동안 했네요. 이제 책 읽을게요.","correct":true},{"t":"아빠는 상관하지 마세요.","mis":"K2-2-u2-X07"},{"t":"(못 들은 척하며 계속 휴대 전화를 본다)","mis":"K2-2-u2-X14"}],"explanation":["높임말로 대답해요.","내 잘못을 알고 말해요.","지도서 107쪽 대본이에요."],"asset":{"type":"scene","icon":"📱👨👧","text":"『국어』 50쪽 그림 다 — 하교 후 휴대 전화만 보는 딸에게 아빠가 「아직도 휴대 전화를 하고 있네.」 하셨어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#9','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',2,'match','auto','『국어』 49쪽 — 상황과 고운 말을 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C4","difficulty":2,"kind":"match","stem":"『국어』 49쪽 — 상황과 고운 말을 이어 보세요.","pairs":[{"l":"아침에 집을 나설 때","r":"학교 다녀오겠습니다."},{"l":"친구에게 놀자고 할 때","r":"점심시간에 나랑 축구할래?"},{"l":"전학 가는 친구와 헤어질 때","r":"너와 헤어져서 아쉬워. 앞으로 자주 연락하자."}],"mis":"K2-2-u2-X01","explanation":["상황마다 어울리는 말이 있어요.","인사·놀이·헤어짐이에요.","49쪽이에요."],"asset":{"type":"passage","lines":["가: 「학교 다녀오겠습니다.」 — 「조심히 다녀오렴.」","나: 「점심시간에 나랑 축구할래?」 — 「좋아! 오늘도 재미있게 놀자.」","다: 「잘 있어. 그동안 고마웠어.」 — 「너와 헤어져서 아쉬워. 앞으로 자주 연락하자.」"],"title":"『국어』 49쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_basic#10','kor',2,2,'u2','L05','g2_2_kor_u2_L05_basic','lesson_basic','K2-2-u2-C4',3,'mc','auto','『국어』 51쪽 (3) — 역할놀이에서 고운 말로 대화를 잘한 친구를 고른 까닭으로 알맞은 것은?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어』 51쪽 (3) — 역할놀이에서 고운 말로 대화를 잘한 친구를 고른 까닭으로 알맞은 것은?","options":[{"t":"다친 친구의 마음을 위로해 주고, 상황에 알맞은 고운 말을 사용했어요","correct":true},{"t":"목소리가 가장 컸어요","mis":"K2-2-u2-X05"},{"t":"가장 빨리 말했어요","mis":"K2-2-u2-X05"}],"explanation":["마음을 헤아렸는지 봐요.","상황에 알맞은지 봐요.","51쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#1','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',2,'mc','auto','『국어』 48쪽 나 — 「내가 만든 것 어때?」에 대답하는 고운 말은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":1,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"『국어』 48쪽 나 — 「내가 만든 것 어때?」에 대답하는 고운 말은?","options":[{"t":"우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.","correct":true},{"t":"별로야.","mis":"K2-2-u2-X02"},{"t":"내가 만든 게 더 멋져.","mis":"K2-2-u2-X02"}],"explanation":["좋은 점을 말해 주었어요.","48쪽 그림 나예요.","기분 좋게 대답해요."],"asset":{"type":"passage","lines":["가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」","나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」","다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」"],"title":"『국어』 48쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#2','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',2,'ox','auto','고운 말은 친구에게만 쓰고, 가족이나 웃어른께는 쓰지 않아도 돼요.',ARRAY['K2-2-u2-X07']::text[],false,'{"seq":2,"concept":"K2-2-u2-C4","difficulty":2,"kind":"ox","stem":"고운 말은 친구에게만 쓰고, 가족이나 웃어른께는 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"친구·가족·선생님 등 누구와 대화할 때나 고운 말을 쓰니까","correct":true},{"t":"가족은 편한 사이니까","mis":"K2-2-u2-X07"}],"mis":"K2-2-u2-X07","explanation":["누구에게나 고운 말이에요.","가족과도 고운 말로 대화해요.","지도서 95쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#3','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',3,'error','auto','승훈이가 늦게 온 민지에게 「너는 맨날 늦는 게으름뱅이야!」라고 했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X02','K2-2-u2-X04']::text[],false,'{"seq":3,"concept":"K2-2-u2-C4","difficulty":3,"kind":"error","stem":"승훈이가 늦게 온 민지에게 「너는 맨날 늦는 게으름뱅이야!」라고 했어요. 무엇이 아쉬운가요?","options":[{"t":"기분이 상하지 않게 「다음부터는 약속 시간을 지키면 좋겠어.」처럼 말해야 해요","correct":true,"mis_target":"K2-2-u2-X02"},{"t":"잘 말했어요","mis":"K2-2-u2-X02"},{"t":"「괜찮아, 늦어도 돼.」라고만 해야 해요","mis":"K2-2-u2-X04"}],"explanation":["내 마음은 말해도 돼요.","다만 고운 말로 말해요.","지도서 107쪽 대본이에요."],"asset":{"type":"scene","icon":"⏰🧒🧒","text":"『국어』 50쪽 그림 나 — 친구가 약속 시간을 지키지 못하고 늦게 와서 승훈이가 한참을 기다렸어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#4','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',3,'error','auto','딸이 아빠께 「아빠는 상관하지 마세요.」라고 대답했어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X07','K2-2-u2-X05']::text[],false,'{"seq":4,"concept":"K2-2-u2-C4","difficulty":3,"kind":"error","stem":"딸이 아빠께 「아빠는 상관하지 마세요.」라고 대답했어요. 무엇이 아쉬운가요?","options":[{"t":"웃어른께 공손하게, 상황에 알맞은 고운 말로 대답해야 해요","correct":true,"mis_target":"K2-2-u2-X07"},{"t":"잘 말했어요","mis":"K2-2-u2-X07"},{"t":"더 큰 소리로 말해야 해요","mis":"K2-2-u2-X05"}],"explanation":["아빠는 걱정하셨어요.","공손하게 대답해요.","50쪽 그림 다예요."],"asset":{"type":"scene","icon":"📱👨👧","text":"『국어』 50쪽 그림 다 — 하교 후 휴대 전화만 보는 딸에게 아빠가 「아직도 휴대 전화를 하고 있네.」 하셨어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#5','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',3,'mc','auto','지도서 107쪽 역할놀이 대본 — 민지가 늦은 까닭을 말하자 승훈이가 한 말로 알맞은 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":5,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"지도서 107쪽 역할놀이 대본 — 민지가 늦은 까닭을 말하자 승훈이가 한 말로 알맞은 것은?","options":[{"t":"그랬구나. 이제 우리 함께 놀자.","correct":true},{"t":"변명하지 마.","mis":"K2-2-u2-X02"},{"t":"너는 집에 가.","mis":"K2-2-u2-X02"}],"explanation":["까닭을 듣고 받아들였어요.","다시 함께 놀자고 했어요.","지도서 107쪽이에요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"승훈아, 내가 늦었지?"},{"who":"승훈","text":"민지야, 기다리느라 힘들었어. 다음부터는 약속 시간을 지키면 좋겠어."},{"who":"민지","text":"미안해. 오다가 오랜만에 만난 친구와 이야기하다가 늦었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#6','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',3,'mc','auto','친구가 「나 받아쓰기에서 100점 받았어!」라고 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02','K2-2-u2-X05']::text[],false,'{"seq":6,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"친구가 「나 받아쓰기에서 100점 받았어!」라고 해요. 알맞은 고운 말은?","options":[{"t":"정말 잘됐다! 날마다 연습하더니 멋지다.","correct":true},{"t":"그게 뭐 어려워?","mis":"K2-2-u2-X02"},{"t":"나도 받을 수 있어.","mis":"K2-2-u2-X05"}],"explanation":["친구의 기쁨에 함께해요.","노력도 알아봐 줘요.","49쪽 활동처럼 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#7','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',3,'mc','auto','『국어』 51쪽 (3) — 역할놀이를 보며 고운 말로 대화를 잘한 친구를 쓸 때 함께 쓸 것은?',ARRAY['K2-2-u2-X17']::text[],false,'{"seq":7,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어』 51쪽 (3) — 역할놀이를 보며 고운 말로 대화를 잘한 친구를 쓸 때 함께 쓸 것은?","options":[{"t":"친구가 한 고운 말과 고른 까닭","correct":true},{"t":"친구 옷의 색깔","mis":"K2-2-u2-X17"},{"t":"친구의 키","mis":"K2-2-u2-X17"}],"explanation":["친구가 한 고운 말을 써요.","고른 까닭도 써요.","51쪽 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#8','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',4,'sa','auto','『국어』 48쪽 — 손자가 할머니께 한 말이에요. 「제 생일을 축하해 주셔서 (     ).」 빈칸에 알맞은 다섯 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C4","difficulty":4,"kind":"sa","stem":"『국어』 48쪽 — 손자가 할머니께 한 말이에요. 「제 생일을 축하해 주셔서 (     ).」 빈칸에 알맞은 다섯 글자를 쓰세요.","answer":["고맙습니다"],"explanation":["고맙습니다예요.","높임말이에요.","48쪽 그림 다예요."],"asset":{"type":"passage","lines":["가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」","나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」","다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」"],"title":"『국어』 48쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#9','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',4,'essay','teacher','『국어』 50쪽 그림 가~다 가운데 하나를 골라, 두 사람이 고운 말로 나누는 대화를 세 마디 이상 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"『국어』 50쪽 그림 가~다 가운데 하나를 골라, 두 사람이 고운 말로 나누는 대화를 세 마디 이상 쓰세요.","answer_guide":{"answer":"예: 선민: 어디 가려고? / 상훈: 응, 답답해서 운동장에 나가고 싶어. / 선민: 다리를 다쳐서 힘들지? 내가 문을 열어 줄게. / 상훈: 도와줘서 고마워.","scoring_points":["상황에 알맞은 대화예요","두 사람 모두 고운 말을 썼어요","세 마디 이상이에요"]},"explanation":["상황을 먼저 살펴요.","두 사람 모두 고운 말을 써요.","지도서 107쪽 대본이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L05_challenge#10','kor',2,2,'u2','L05','g2_2_kor_u2_L05_challenge','lesson_challenge','K2-2-u2-C4',4,'essay','teacher','오늘 가족이나 친구와 고운 말로 나눈 대화를 떠올려, 누구와 어떤 말을 주고받았는지와 그때의 기분을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"오늘 가족이나 친구와 고운 말로 나눈 대화를 떠올려, 누구와 어떤 말을 주고받았는지와 그때의 기분을 쓰세요.","answer_guide":{"answer":"예: 아침에 아빠께 「학교 다녀오겠습니다.」 하고 인사했더니 「조심히 다녀오렴.」 하셨어요. 기분이 좋았어요.","scoring_points":["누구와 대화했는지 있어요","주고받은 고운 말이 있어요","기분을 썼어요"]},"explanation":["누구와 대화했는지 써요.","그때 기분도 써요.","49쪽 계획하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#1','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 52~53쪽 — 악어 크니프의 고민은 무엇인가요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":1,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 52~53쪽 — 악어 크니프의 고민은 무엇인가요?","options":[{"t":"아무도 자기와 놀아 주지 않는 것","correct":true},{"t":"목소리가 너무 작은 것","mis":"K2-2-u2-X03"},{"t":"달리기를 못하는 것","mis":"K2-2-u2-X03"}],"explanation":["아무도 놀아 주지 않아요.","그래서 속상해요.","지도서 109쪽이에요."],"asset":{"type":"passage","lines":["악어 크니프는 힘도 세고 달리기도 잘하지만, 아무도 놀아 주지 않아 늘 혼자였어요.","그때 방울새 속삭이의 아주 작은 노랫소리가 들렸어요.","둘은 서로의 목소리가 좋다고 말해 주었어요.","「아무도 날 좋아하지 않아.」 하는 크니프에게 속삭이는 친구 사귀는 방법을 알려 주었어요."],"title":"『국어』 52~53쪽 「크니프의 친구 사귀기」(윤선아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#2','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 53쪽 2번 (1) — 속삭이는 크니프의 어떤 점이 멋있다고 했나요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 53쪽 2번 (1) — 속삭이는 크니프의 어떤 점이 멋있다고 했나요?","options":[{"t":"목소리가 커서 멋있다고 했어요","correct":true},{"t":"이빨이 뾰족해서 멋있다고 했어요","mis":"K2-2-u2-X03"},{"t":"노래를 잘 불러서 멋있다고 했어요","mis":"K2-2-u2-X03"}],"explanation":["큰 목소리예요.","좋은 점을 찾아 주었어요.","53쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"크니프","text":"너는 목소리가 참 예쁘구나. 정말 좋겠다."},{"who":"속삭이","text":"너는 목소리가 커서 멋있는걸."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#3','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C5',1,'mc','auto','『국어』 54쪽 — 「칭찬」은 무엇인가요?',ARRAY['K2-2-u2-X08','K2-2-u2-X11']::text[],false,'{"seq":3,"concept":"K2-2-u2-C5","difficulty":1,"kind":"mc","stem":"『국어』 54쪽 — 「칭찬」은 무엇인가요?","options":[{"t":"상대가 잘하는 점이나 노력하는 점, 좋은 점 등을 높이 평가해 주는 것","correct":true},{"t":"다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것","mis":"K2-2-u2-X08"},{"t":"상대의 잘못을 고치라고 꾸짖는 것","mis":"K2-2-u2-X11"}],"explanation":["좋은 점을 높이 평가해요.","54쪽 도움말이에요.","두 번째 보기는 조언이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#4','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C5',1,'mc','auto','『국어』 54쪽 — 「조언」은 무엇인가요?',ARRAY['K2-2-u2-X08']::text[],false,'{"seq":4,"concept":"K2-2-u2-C5","difficulty":1,"kind":"mc","stem":"『국어』 54쪽 — 「조언」은 무엇인가요?","options":[{"t":"다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것","correct":true},{"t":"상대가 잘하는 점을 높이 평가해 주는 것","mis":"K2-2-u2-X08"},{"t":"상대의 일을 대신 해 주는 것","mis":"K2-2-u2-X08"}],"explanation":["도움이 되도록 알려 줘요.","54쪽 도움말이에요.","첫 번째 보기는 칭찬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#5','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C5',2,'mc','auto','속삭이가 크니프에게 한 「친구를 만나면 먼저 반갑게 인사해 봐!」는 무엇인가요?',ARRAY['K2-2-u2-X08']::text[],false,'{"seq":5,"concept":"K2-2-u2-C5","difficulty":2,"kind":"mc","stem":"속삭이가 크니프에게 한 「친구를 만나면 먼저 반갑게 인사해 봐!」는 무엇인가요?","options":[{"t":"조언","correct":true},{"t":"칭찬","mis":"K2-2-u2-X08"},{"t":"사과","mis":"K2-2-u2-X08"}],"explanation":["어려움을 돕는 말이에요.","그래서 조언이에요.","54쪽 (2)예요."],"asset":{"type":"speech","turns":[{"who":"크니프","text":"아무도 날 좋아하지 않아. 아무도 나랑 이야기도 하지 않고, 놀려고 하지도 않아."},{"who":"속삭이","text":"친구를 만나면 먼저 반갑게 인사해 봐!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#6','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C6',2,'mc','auto','『국어』 55쪽 — 「미술 작품을 완성하려고 끝까지 노력하는 네가 정말 대단해.」는 어떻게 칭찬한 것인가요?',ARRAY['K2-2-u2-X09','K2-2-u2-X08']::text[],false,'{"seq":6,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"『국어』 55쪽 — 「미술 작품을 완성하려고 끝까지 노력하는 네가 정말 대단해.」는 어떻게 칭찬한 것인가요?","options":[{"t":"열심히 노력하는 점을 찾아 칭찬했어요","correct":true},{"t":"좋은 점을 크게 부풀려 칭찬했어요","mis":"K2-2-u2-X09"},{"t":"문제를 해결할 방법을 알려 주었어요","mis":"K2-2-u2-X08"}],"explanation":["끝까지 노력한 점이에요.","55쪽 예시 답안이에요.","노력을 칭찬했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#7','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C6',2,'mc','auto','지도서 110쪽 — 이 칭찬은 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X09']::text[],false,'{"seq":7,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"지도서 110쪽 — 이 칭찬은 무엇이 아쉬운가요?","options":[{"t":"잘못한 점과 함께 말해 칭찬으로 느껴지지 않아요","correct":true},{"t":"까닭을 너무 자세히 말했어요","mis":"K2-2-u2-X09"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X09"}],"explanation":["「이상하기는 하지만」이 문제예요.","잘한 점만 진심으로 말해요.","지도서 110쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"작품이 이상하기는 하지만 끝까지 열심히 완성하기는 했네."},{"who":"친구 2","text":"작품이 이상하다니……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#8','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C7',2,'mc','auto','『국어』 56쪽 — 「나도 너처럼 줄넘기를 잘하고 싶은데…….」에 바르게 조언한 말은?',ARRAY['K2-2-u2-X12','K2-2-u2-X11']::text[],false,'{"seq":8,"concept":"K2-2-u2-C7","difficulty":2,"kind":"mc","stem":"『국어』 56쪽 — 「나도 너처럼 줄넘기를 잘하고 싶은데…….」에 바르게 조언한 말은?","options":[{"t":"날마다 10분씩 줄넘기 연습을 해 보면 어떨까?","correct":true},{"t":"그냥 하면 돼.","mis":"K2-2-u2-X12"},{"t":"너는 왜 그렇게 못하니?","mis":"K2-2-u2-X11"}],"explanation":["해결 방법을 알려 주었어요.","「~하면 어떨까?」로 부드럽게 말했어요.","56쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#9','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C5',2,'ox','auto','칭찬이나 조언을 주고받으면 말하는 사람과 더 가까워질 수 있어요.',ARRAY['K2-2-u2-X10']::text[],false,'{"seq":9,"concept":"K2-2-u2-C5","difficulty":2,"kind":"ox","stem":"칭찬이나 조언을 주고받으면 말하는 사람과 더 가까워질 수 있어요.","answer":"O","reason_options":[{"t":"서로를 생각해 주는 마음이 전해지니까","correct":true},{"t":"칭찬을 들으면 늘 선물을 받으니까","mis":"K2-2-u2-X10"}],"mis":"K2-2-u2-X10","explanation":["마음이 전해져요.","그래서 가까워져요.","59쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_basic#10','kor',2,2,'u2','L07','g2_2_kor_u2_L07_basic','lesson_basic','K2-2-u2-C7',3,'mc','auto','지도서 112쪽 — 이 조언은 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X12','K2-2-u2-X11']::text[],false,'{"seq":10,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"지도서 112쪽 — 이 조언은 무엇이 아쉬운가요?","options":[{"t":"상대를 비난하며 명령하듯 말해 위하는 마음이 느껴지지 않아요","correct":true},{"t":"해결 방법을 너무 자세히 알려 주었어요","mis":"K2-2-u2-X12"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X11"}],"explanation":["「게으르니?」는 비난이에요.","걱정하는 마음을 담아요.","지도서 112쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"정리할 게 너무 많아. 귀찮으니까 정리하지 말고 사물함에 다 넣어야겠어."},{"who":"친구 2","text":"넌 왜 그렇게 게으르니? 제대로 정리 좀 해!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#1','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C6',2,'mc','auto','『국어』 55쪽 — 「너는 참 친절해. 내가 궁금한 것을 물어보면 늘 잘 알려 줘.」는 어떻게 칭찬한 것인가요?',ARRAY['K2-2-u2-X10','K2-2-u2-X08']::text[],false,'{"seq":1,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"『국어』 55쪽 — 「너는 참 친절해. 내가 궁금한 것을 물어보면 늘 잘 알려 줘.」는 어떻게 칭찬한 것인가요?","options":[{"t":"칭찬하는 점과 그 까닭이 드러나게 칭찬했어요","correct":true},{"t":"결과만 보고 칭찬했어요","mis":"K2-2-u2-X10"},{"t":"문제를 해결할 방법을 알려 주었어요","mis":"K2-2-u2-X08"}],"explanation":["친절하다는 까닭을 말했어요.","55쪽 예시 답안이에요.","까닭이 있으면 진심이 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#2','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C7',2,'mc','auto','『국어』 56쪽 — 「실수해서 무척 속상했구나. 그런데 실수는 누구나 하는 거니까 너무 실망하지 마.」는 어떻게 조언한 것인가요?',ARRAY['K2-2-u2-X11','K2-2-u2-X08']::text[],false,'{"seq":2,"concept":"K2-2-u2-C7","difficulty":2,"kind":"mc","stem":"『국어』 56쪽 — 「실수해서 무척 속상했구나. 그런데 실수는 누구나 하는 거니까 너무 실망하지 마.」는 어떻게 조언한 것인가요?","options":[{"t":"듣는 사람의 마음에 공감하며 격려했어요","correct":true},{"t":"상대를 비난하며 지시했어요","mis":"K2-2-u2-X11"},{"t":"칭찬하는 까닭을 말했어요","mis":"K2-2-u2-X08"}],"explanation":["속상한 마음을 알아주었어요.","56쪽 예시 답안이에요.","격려도 조언이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
