INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#4','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C7',3,'error','auto','조언하는 방법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#5','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C7',3,'error','auto','지도서 112쪽 — 이 조언은 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X13','K2-2-u2-X12']::text[],false,'{"seq":5,"concept":"K2-2-u2-C7","difficulty":3,"kind":"error","stem":"지도서 112쪽 — 이 조언은 무엇이 아쉬운가요?","options":[{"t":"상대를 무시하듯 말해 괜히 말했다는 생각이 들 수 있어요","correct":true,"mis_target":"K2-2-u2-X13"},{"t":"잘 말했어요","mis":"K2-2-u2-X13"},{"t":"해결 방법을 너무 많이 알려 주었어요","mis":"K2-2-u2-X12"}],"explanation":["고민을 가볍게 넘겼어요.","먼저 마음을 알아줘요.","지도서 112쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 왜 자꾸 실수하는 걸까? 실수하지 않으려면 어떻게 해야 할까?"},{"who":"친구 2","text":"야, 뭐 그런 일로 고민해? 누구나 다 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#6','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C6',3,'mc','auto','지도서 110쪽 — 칭찬을 들은 친구가 「왜 그렇게 생각하는 걸까?」 한 까닭은?',ARRAY['K2-2-u2-X09','K2-2-u2-X08']::text[],false,'{"seq":6,"concept":"K2-2-u2-C6","difficulty":3,"kind":"mc","stem":"지도서 110쪽 — 칭찬을 들은 친구가 「왜 그렇게 생각하는 걸까?」 한 까닭은?","options":[{"t":"칭찬하는 까닭을 말하지 않았기 때문이에요","correct":true},{"t":"칭찬을 너무 길게 했기 때문이에요","mis":"K2-2-u2-X09"},{"t":"칭찬이 아니라 조언이었기 때문이에요","mis":"K2-2-u2-X08"}],"explanation":["까닭이 없었어요.","까닭을 말해야 진심이 전해져요.","지도서 110쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"너는 참 친절해."},{"who":"친구 2","text":"왜 그렇게 생각하는 걸까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#7','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C7',3,'mc','auto','지도서 113쪽 — 조언할 때 알맞은 태도는?',ARRAY['K2-2-u2-X11']::text[],false,'{"seq":7,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"지도서 113쪽 — 조언할 때 알맞은 태도는?","options":[{"t":"상대를 도우려는 마음으로 부드러운 말투와 표정으로 말해요","correct":true},{"t":"상대가 원하지 않아도 계속 잔소리해요","mis":"K2-2-u2-X11"},{"t":"상대의 잘못을 친구들 앞에서 크게 말해요","mis":"K2-2-u2-X11"}],"explanation":["도우려는 마음이 먼저예요.","부드러운 말투와 표정이에요.","지도서 113쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#8','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C5',4,'sa','auto','「다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C5","difficulty":4,"kind":"sa","stem":"「다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["조언"],"explanation":["조언이에요.","54쪽 도움말이에요.","칭찬과 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#9','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C6',4,'essay','teacher','『국어』 57쪽 5번 — 칭찬하고 싶은 친구 한 명을 골라, 칭찬하는 점과 그 까닭이 드러나게 칭찬하는 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C6","difficulty":4,"kind":"essay","stem":"『국어』 57쪽 5번 — 칭찬하고 싶은 친구 한 명을 골라, 칭찬하는 점과 그 까닭이 드러나게 칭찬하는 말을 쓰세요.","answer_guide":{"answer":"예: 민수야, 너는 시간 약속을 참 잘 지켜. 지각한 적이 한 번도 없어서 정말 대단해.","scoring_points":["칭찬하는 점이 있어요","까닭이 있어요","부풀리지 않고 진심이에요"]},"explanation":["무엇을 칭찬할지 정해요.","까닭을 함께 써요.","지도서 113쪽 예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L07_challenge#10','kor',2,2,'u2','L07','g2_2_kor_u2_L07_challenge','lesson_challenge','K2-2-u2-C7',4,'essay','teacher','「정리할 게 너무 많아. 귀찮으니까 정리하지 말고 사물함에 다 넣어야겠어.」 하는 친구에게 걱정하는 마음을 담아 조언하는 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u2-C7","difficulty":4,"kind":"essay","stem":"「정리할 게 너무 많아. 귀찮으니까 정리하지 말고 사물함에 다 넣어야겠어.」 하는 친구에게 걱정하는 마음을 담아 조언하는 말을 쓰세요.","answer_guide":{"answer":"예: 그러면 사물함을 열었을 때 물건이 쏟아져 다칠 수도 있어. 정리해서 넣어 두는 게 어때? — 「~하지 마」보다 「~하면 좋겠어」처럼 바라는 행동을 말하면 좋아요.","scoring_points":["걱정하는 마음이 드러나요","해결 방법을 알려 주었어요","비난하거나 명령하지 않았어요"]},"explanation":["걱정하는 마음을 담아요.","바라는 행동을 말해요.","56쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_basic#1','kor',2,2,'u2','L09','g2_2_kor_u2_L09_basic','lesson_basic','K2-2-u2-C8',1,'mc','auto','『국어』 60쪽 (1) — 진아는 선우와 함께 무엇을 하고 싶어 했나요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":1,"concept":"K2-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 60쪽 (1) — 진아는 선우와 함께 무엇을 하고 싶어 했나요?","options":[{"t":"미끄럼틀 타기나 술래잡기 같은 놀이를 함께 하고 싶어 했어요","correct":true},{"t":"휴대 전화로 게임을 하고 싶어 했어요","mis":"K2-2-u2-X03"},{"t":"혼자 책을 읽고 싶어 했어요","mis":"K2-2-u2-X03"}],"explanation":["함께 놀고 싶었어요.","60쪽 예시 답안이에요.","진아의 말을 읽어요."],"asset":{"type":"speech","turns":[{"who":"진아","text":"선우야, 우리 뭐 하고 놀까? 미끄럼틀 탈까?"},{"who":"선우","text":"(휴대 전화를 보며) 진아야, 잠깐만. 이것만 좀 하고……."},{"who":"진아","text":"아니면 술래잡기할까?"},{"who":"선우","text":"어……. 어……."},{"who":"진아","text":"선우야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_basic#2','kor',2,2,'u2','L09','g2_2_kor_u2_L09_basic','lesson_basic','K2-2-u2-C8',1,'mc','auto','『국어』 60쪽 (2) — 진아가 말할 때 선우는 어떻게 반응했나요?',ARRAY['K2-2-u2-X14']::text[],false,'{"seq":2,"concept":"K2-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 60쪽 (2) — 진아가 말할 때 선우는 어떻게 반응했나요?","options":[{"t":"휴대 전화만 쳐다보면서 건성으로 대답했어요","correct":true},{"t":"진아를 바라보며 고개를 끄덕였어요","mis":"K2-2-u2-X14"},{"t":"웃으며 좋다고 했어요","mis":"K2-2-u2-X14"}],"explanation":["휴대 전화만 봤어요.","건성으로 대답했어요.","60쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"진아","text":"선우야, 우리 뭐 하고 놀까? 미끄럼틀 탈까?"},{"who":"선우","text":"(휴대 전화를 보며) 진아야, 잠깐만. 이것만 좀 하고……."},{"who":"진아","text":"아니면 술래잡기할까?"},{"who":"선우","text":"어……. 어……."},{"who":"진아","text":"선우야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_basic#3','kor',2,2,'u2','L09','g2_2_kor_u2_L09_basic','lesson_basic','K2-2-u2-C2',1,'mc','auto','『국어』 60쪽 (3) — 선우의 반응을 보고 진아는 어떤 기분이었을까요?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":3,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 60쪽 (3) — 선우의 반응을 보고 진아는 어떤 기분이었을까요?","options":[{"t":"서운했을 것 같아요","correct":true},{"t":"신났을 것 같아요","mis":"K2-2-u2-X03"},{"t":"편안했을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["서운하거나 화가 났을 거예요.","60쪽 예시 답안이에요.","반응이 기분을 바꿔요."],"asset":{"type":"speech","turns":[{"who":"진아","text":"선우야, 우리 뭐 하고 놀까? 미끄럼틀 탈까?"},{"who":"선우","text":"(휴대 전화를 보며) 진아야, 잠깐만. 이것만 좀 하고……."},{"who":"진아","text":"아니면 술래잡기할까?"},{"who":"선우","text":"어……. 어……."},{"who":"진아","text":"선우야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
