INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_basic#9','kor',2,2,'u2','L09','g2_2_kor_u2_L09_basic','lesson_basic','K2-2-u2-C8',2,'ox','auto','대화할 때에는 말의 내용만 좋으면 표정이나 말투는 상관없어요.',ARRAY['K2-2-u2-X14']::text[],false,'{"seq":9,"concept":"K2-2-u2-C8","difficulty":2,"kind":"ox","stem":"대화할 때에는 말의 내용만 좋으면 표정이나 말투는 상관없어요.","answer":"X","reason_options":[{"t":"표정, 목소리, 행동이 대화 상황에 어울리도록 반응하는 것이 중요하니까","correct":true},{"t":"말은 귀로만 듣는 것이니까","mis":"K2-2-u2-X14"}],"mis":"K2-2-u2-X14","explanation":["표정과 말투도 중요해요.","62쪽 도움말이에요.","지도서 119쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
