INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_challenge#7','kor',2,2,'u2','L09','g2_2_kor_u2_L09_challenge','lesson_challenge','K2-2-u2-C7',3,'mc','auto','지도서 117쪽 — 『국어』 60쪽 만화의 선우에게 할 수 있는 조언으로 알맞은 것은?',ARRAY['K2-2-u2-X14','K2-2-u2-X11']::text[],false,'{"seq":7,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"지도서 117쪽 — 『국어』 60쪽 만화의 선우에게 할 수 있는 조언으로 알맞은 것은?","options":[{"t":"친구가 말할 때는 휴대 전화를 내려놓고 친구를 바라보며 들어 봐","correct":true},{"t":"휴대 전화를 더 오래 보면 돼","mis":"K2-2-u2-X14"},{"t":"넌 왜 맨날 그래?","mis":"K2-2-u2-X11"}],"explanation":["바라는 행동을 알려 줘요.","앞 차시 조언 방법이에요.","지도서 117쪽이에요."],"asset":{"type":"speech","turns":[{"who":"진아","text":"선우야, 우리 뭐 하고 놀까? 미끄럼틀 탈까?"},{"who":"선우","text":"(휴대 전화를 보며) 진아야, 잠깐만. 이것만 좀 하고……."},{"who":"진아","text":"아니면 술래잡기할까?"},{"who":"선우","text":"어……. 어……."},{"who":"진아","text":"선우야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_challenge#8','kor',2,2,'u2','L09','g2_2_kor_u2_L09_challenge','lesson_challenge','K2-2-u2-C8',4,'sa','auto','『국어』 62쪽 도움말이에요. 「대화할 때에는 표정, 목소리, (  )이 대화 상황에 어울리도록 반응하는 것이 중요해요.」 빈칸에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C8","difficulty":4,"kind":"sa","stem":"『국어』 62쪽 도움말이에요. 「대화할 때에는 표정, 목소리, (  )이 대화 상황에 어울리도록 반응하는 것이 중요해요.」 빈칸에 알맞은 두 글자를 쓰세요.","answer":["행동"],"explanation":["행동이에요.","62쪽 도움말이에요.","몸짓도 반응이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_challenge#9','kor',2,2,'u2','L09','g2_2_kor_u2_L09_challenge','lesson_challenge','K2-2-u2-C8',4,'essay','teacher','『국어』 61쪽 그림 가~다 가운데 하나를 골라, 적절하게 반응하는 말과 함께 지을 표정이나 몸짓을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C8","difficulty":4,"kind":"essay","stem":"『국어』 61쪽 그림 가~다 가운데 하나를 골라, 적절하게 반응하는 말과 함께 지을 표정이나 몸짓을 쓰세요.","answer_guide":{"answer":"예: 그림 다 — 친구의 말을 끝까지 들은 뒤 걱정하는 표정으로 「무서운 꿈을 꿔서 많이 놀랐겠다. 무슨 꿈이었어?」라고 해요.","scoring_points":["그림의 상황에 맞아요","공감하는 말이 있어요","표정이나 몸짓을 썼어요"]},"explanation":["말과 표정을 함께 써요.","상황에 알맞게 반응해요.","62쪽 (2)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L09_challenge#10','kor',2,2,'u2','L09','g2_2_kor_u2_L09_challenge','lesson_challenge','K2-2-u2-C8',4,'essay','teacher','『국어활동』 31쪽처럼 평소 내가 친구의 말을 들을 때의 모습을 돌아보고, 더 노력할 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u2-C8","difficulty":4,"kind":"essay","stem":"『국어활동』 31쪽처럼 평소 내가 친구의 말을 들을 때의 모습을 돌아보고, 더 노력할 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 나는 친구가 말할 때 끝까지 듣지 않고 끼어들 때가 있어요. 앞으로는 친구의 말이 끝날 때까지 기다린 뒤 말할게요.","scoring_points":["내 모습을 솔직하게 돌아보았어요","적절한 반응과 관련된 노력할 점이에요"]},"explanation":["내 대화 습관을 떠올려요.","노력할 점을 정해요.","국어활동 31쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_basic#1','kor',2,2,'u2','L11','g2_2_kor_u2_L11_basic','lesson_basic','K2-2-u2-C10',1,'mc','auto','『국어』 64쪽 「이런 활동 어때요」에 나온 활동은?',ARRAY['K2-2-u2-X17']::text[],false,'{"seq":1,"concept":"K2-2-u2-C10","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 「이런 활동 어때요」에 나온 활동은?","options":[{"t":"알림판에 칭찬이나 조언 쪽지 붙이기","correct":true},{"t":"노래 자랑하기","mis":"K2-2-u2-X17"},{"t":"교실 대청소하기","mis":"K2-2-u2-X17"}],"explanation":["알림판 쪽지예요.","64쪽이에요.","칭찬과 조언을 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_basic#2','kor',2,2,'u2','L11','g2_2_kor_u2_L11_basic','lesson_basic','K2-2-u2-C10',1,'mc','auto','『국어』 64쪽 — 「칭찬합시다」 알림판에 붙이는 쪽지에 쓸 것은?',ARRAY['K2-2-u2-X11','K2-2-u2-X17']::text[],false,'{"seq":2,"concept":"K2-2-u2-C10","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 — 「칭찬합시다」 알림판에 붙이는 쪽지에 쓸 것은?","options":[{"t":"칭찬하고 싶은 친구의 이름과 칭찬하는 내용","correct":true},{"t":"친구가 잘못한 일","mis":"K2-2-u2-X11"},{"t":"내 이름만","mis":"K2-2-u2-X17"}],"explanation":["이름과 칭찬하는 내용이에요.","64쪽 ①이에요.","까닭도 드러나게 써요."],"asset":{"type":"passage","lines":["칭찬합시다 ① 평소 고운 말을 잘 쓰는 서율이를 칭찬합니다.","칭찬합시다 ② 음식을 남기지 않고 골고루 잘 먹는 지훈이를 칭찬합니다.","칭찬합시다 ③ 무거운 짐을 같이 들어 준 하린이를 칭찬합니다.","조언을 구해요: 밤에 자려고 누우면 무서운 생각이 들 때가 많아요.","조언 ① 즐거웠던 일을 떠올리면 무서운 생각이 들지 않을 거야.","조언 ② 좋아하는 물건을 머리맡에 두고 자는 건 어때?","조언 ③ 자기 전에 무서운 이야기가 나오는 책은 읽지 않는 것이 좋아."],"title":"『국어』 64쪽 알림판 쪽지 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
