INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_basic#6','kor',2,2,'u2','L11','g2_2_kor_u2_L11_basic','lesson_basic','K2-2-u2-C10',2,'mc','auto','지도서 121쪽 — 조언 쪽지에 조언하는 사람의 이름을 밝혀 쓰는 까닭은?',ARRAY['K2-2-u2-X17']::text[],false,'{"seq":6,"concept":"K2-2-u2-C10","difficulty":2,"kind":"mc","stem":"지도서 121쪽 — 조언 쪽지에 조언하는 사람의 이름을 밝혀 쓰는 까닭은?","options":[{"t":"자기 글에 책임감을 갖고, 도움을 주려는 마음으로 쓰려고","correct":true},{"t":"친구에게 내 이름을 자랑하려고","mis":"K2-2-u2-X17"},{"t":"쪽지 칸을 채우려고","mis":"K2-2-u2-X17"}],"explanation":["책임감 있게 써요.","장난이나 비난은 안 돼요.","지도서 121쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_basic#7','kor',2,2,'u2','L11','g2_2_kor_u2_L11_basic','lesson_basic','K2-2-u2-C6',2,'mc','auto','지도서 121쪽 「현명한 칭찬」 — 결과보다 과정을 칭찬한 말은?',ARRAY['K2-2-u2-X10']::text[],false,'{"seq":7,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"지도서 121쪽 「현명한 칭찬」 — 결과보다 과정을 칭찬한 말은?","options":[{"t":"날마다 끝까지 포기하지 않고 연습한 네가 정말 멋져.","correct":true},{"t":"1등 했으니까 네가 최고야.","mis":"K2-2-u2-X10"},{"t":"상 받으면 선물 줄게.","mis":"K2-2-u2-X10"}],"explanation":["노력과 과정을 칭찬했어요.","의욕을 북돋워요.","지도서 121쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_basic#8','kor',2,2,'u2','L11','g2_2_kor_u2_L11_basic','lesson_basic','K2-2-u2-C10',2,'mc','auto','지도서 123쪽 — 칭찬이나 조언 책갈피에 들어갈 문구로 알맞은 것은?',ARRAY['K2-2-u2-X11','K2-2-u2-X02']::text[],false,'{"seq":8,"concept":"K2-2-u2-C10","difficulty":2,"kind":"mc","stem":"지도서 123쪽 — 칭찬이나 조언 책갈피에 들어갈 문구로 알맞은 것은?","options":[{"t":"너무 걱정하지 마. 꾸준히 연습하면 잘할 수 있어.","correct":true},{"t":"너는 왜 맨날 그래?","mis":"K2-2-u2-X11"},{"t":"내가 너보다 잘해.","mis":"K2-2-u2-X02"}],"explanation":["고운 말로 격려했어요.","지도서 123쪽이에요.","책갈피 선물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
