INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#2','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',2,'mc','auto','지도서 121쪽 — 칭찬·조언 알림판을 어떻게 운영하면 좋을까요?',ARRAY['K2-2-u2-X17']::text[],false,'{"seq":2,"concept":"K2-2-u2-C10","difficulty":2,"kind":"mc","stem":"지도서 121쪽 — 칭찬·조언 알림판을 어떻게 운영하면 좋을까요?","options":[{"t":"꾸준히 운영해서 서로 배려하고 도와주는 반 분위기를 만들어요","correct":true},{"t":"한 번만 하고 떼어 내요","mis":"K2-2-u2-X17"},{"t":"칭찬받은 친구만 볼 수 있게 숨겨요","mis":"K2-2-u2-X17"}],"explanation":["꾸준히 운영해요.","지도서 121쪽 정리예요.","배려하는 반이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#3','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',3,'error','auto','한 친구가 칭찬 쪽지에 「지훈이를 칭찬합니다.」라고만 썼어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X17','K2-2-u2-X09']::text[],false,'{"seq":3,"concept":"K2-2-u2-C10","difficulty":3,"kind":"error","stem":"한 친구가 칭찬 쪽지에 「지훈이를 칭찬합니다.」라고만 썼어요. 무엇이 아쉬운가요?","options":[{"t":"무엇을 칭찬하는지 내용과 까닭이 없어요","correct":true,"mis_target":"K2-2-u2-X17"},{"t":"잘 썼어요","mis":"K2-2-u2-X09"},{"t":"지훈이의 이름을 빼야 해요","mis":"K2-2-u2-X17"}],"explanation":["칭찬하는 내용이 빠졌어요.","까닭이 드러나게 써요.","지도서 121쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#4','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',3,'error','auto','한 친구가 조언 쪽지에 「너는 맨날 무서워하는 겁쟁이야. 그만 무서워해.」라고 썼어요. 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X11','K2-2-u2-X17']::text[],false,'{"seq":4,"concept":"K2-2-u2-C10","difficulty":3,"kind":"error","stem":"한 친구가 조언 쪽지에 「너는 맨날 무서워하는 겁쟁이야. 그만 무서워해.」라고 썼어요. 무엇이 아쉬운가요?","options":[{"t":"비난하며 명령하듯 썼어요 — 도움이 되는 방법을 부드럽게 써야 해요","correct":true,"mis_target":"K2-2-u2-X11"},{"t":"잘 썼어요","mis":"K2-2-u2-X11"},{"t":"글씨를 더 크게 써야 해요","mis":"K2-2-u2-X17"}],"explanation":["「겁쟁이」는 비난이에요.","해결 방법을 써요.","64쪽 쪽지와 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#5','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C6',3,'mc','auto','『국어』 64쪽 — 「무거운 짐을 같이 들어 준 하린이를 칭찬합니다.」에서 칭찬하는 점은?',ARRAY['K2-2-u2-X10']::text[],false,'{"seq":5,"concept":"K2-2-u2-C6","difficulty":3,"kind":"mc","stem":"『국어』 64쪽 — 「무거운 짐을 같이 들어 준 하린이를 칭찬합니다.」에서 칭찬하는 점은?","options":[{"t":"친구를 도와준 행동","correct":true},{"t":"하린이가 입은 옷","mis":"K2-2-u2-X10"},{"t":"하린이가 받은 상","mis":"K2-2-u2-X10"}],"explanation":["도와준 행동이에요.","행동을 칭찬했어요.","64쪽 쪽지예요."],"asset":{"type":"passage","lines":["칭찬합시다 ① 평소 고운 말을 잘 쓰는 서율이를 칭찬합니다.","칭찬합시다 ② 음식을 남기지 않고 골고루 잘 먹는 지훈이를 칭찬합니다.","칭찬합시다 ③ 무거운 짐을 같이 들어 준 하린이를 칭찬합니다.","조언을 구해요: 밤에 자려고 누우면 무서운 생각이 들 때가 많아요.","조언 ① 즐거웠던 일을 떠올리면 무서운 생각이 들지 않을 거야.","조언 ② 좋아하는 물건을 머리맡에 두고 자는 건 어때?","조언 ③ 자기 전에 무서운 이야기가 나오는 책은 읽지 않는 것이 좋아."],"title":"『국어』 64쪽 알림판 쪽지 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#6','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',3,'mc','auto','지도서 121쪽 — 칭찬 쪽지를 하나도 받지 못해 소외되는 친구가 없게 하려면?',ARRAY['K2-2-u2-X17']::text[],false,'{"seq":6,"concept":"K2-2-u2-C10","difficulty":3,"kind":"mc","stem":"지도서 121쪽 — 칭찬 쪽지를 하나도 받지 못해 소외되는 친구가 없게 하려면?","options":[{"t":"모든 친구가 쪽지를 받도록 칭찬할 친구를 골고루 정해요","correct":true},{"t":"친한 친구에게만 써요","mis":"K2-2-u2-X17"},{"t":"쪽지 활동을 그만해요","mis":"K2-2-u2-X17"}],"explanation":["골고루 정해요.","지도서 121쪽이에요.","모두가 칭찬받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#7','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C7',3,'mc','auto','「조언을 구해요」에 붙은 고민이에요. 「급식에서 싫어하는 반찬이 나오면 먹기 힘들어요.」 알맞은 조언은?',ARRAY['K2-2-u2-X11','K2-2-u2-X12']::text[],false,'{"seq":7,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"「조언을 구해요」에 붙은 고민이에요. 「급식에서 싫어하는 반찬이 나오면 먹기 힘들어요.」 알맞은 조언은?","options":[{"t":"처음에는 조금씩 먹어 보면 어떨까? 맛에 천천히 익숙해질 수 있어.","correct":true},{"t":"편식쟁이구나.","mis":"K2-2-u2-X11"},{"t":"그냥 먹으면 돼.","mis":"K2-2-u2-X12"}],"explanation":["방법을 알려 주었어요.","부드럽게 말했어요.","조언 쪽지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#8','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',4,'sa','auto','『국어』 64쪽 — 칭찬하고 싶은 친구의 이름과 칭찬하는 내용을 쓴 쪽지를 붙이는 알림판의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u2-C10","difficulty":4,"kind":"sa","stem":"『국어』 64쪽 — 칭찬하고 싶은 친구의 이름과 칭찬하는 내용을 쓴 쪽지를 붙이는 알림판의 이름을 쓰세요.","answer":["칭찬합시다"],"explanation":["「칭찬합시다」예요.","64쪽 ①이에요.","조언은 「조언을 구해요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#9','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',4,'essay','teacher','「칭찬합시다」 알림판에 붙일 칭찬 쪽지를 쓰세요. 친구 이름·칭찬하는 내용·그 까닭이 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u2-C10","difficulty":4,"kind":"essay","stem":"「칭찬합시다」 알림판에 붙일 칭찬 쪽지를 쓰세요. 친구 이름·칭찬하는 내용·그 까닭이 드러나게 쓰세요.","answer_guide":{"answer":"예: 칭찬하고 싶은 친구: 도윤 / 쉬는 시간마다 교실 바닥에 떨어진 쓰레기를 주워서 우리 반이 깨끗해졌어요. 도윤이를 칭찬합니다.","scoring_points":["친구 이름이 있어요","칭찬하는 내용이 있어요","까닭이 드러나요"]},"explanation":["누구에게 · 무엇을 · 왜.","세 가지를 다 써요.","64쪽 쪽지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_L11_challenge#10','kor',2,2,'u2','L11','g2_2_kor_u2_L11_challenge','lesson_challenge','K2-2-u2-C10',4,'essay','teacher','「조언을 구해요」에 붙일 고민 하나를 쓰고, 그 고민에 대한 조언 쪽지도 내 이름을 밝혀 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u2-C10","difficulty":4,"kind":"essay","stem":"「조언을 구해요」에 붙일 고민 하나를 쓰고, 그 고민에 대한 조언 쪽지도 내 이름을 밝혀 쓰세요.","answer_guide":{"answer":"예: 고민: 발표할 때 목소리가 작아져요. / 조언(조언한 친구: 지아): 발표하기 전에 짝 앞에서 한 번 연습해 보면 어떨까? 자신감이 생길 거야.","scoring_points":["고민이 있어요","해결 방법이 담긴 조언이에요","조언한 사람 이름을 밝혔어요"]},"explanation":["고민을 먼저 써요.","방법을 담아 조언해요.","64쪽 ②③이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#1','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C1',1,'mc','auto','고운 말의 뜻으로 알맞은 것은?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":1,"concept":"K2-2-u2-C1","difficulty":1,"kind":"mc","stem":"고운 말의 뜻으로 알맞은 것은?","options":[{"t":"다른 사람의 마음을 헤아려서 부드럽게 하는 말","correct":true},{"t":"다른 사람보다 크게 하는 말","mis":"K2-2-u2-X05"},{"t":"친한 친구끼리만 하는 말","mis":"K2-2-u2-X05"}],"explanation":["마음을 헤아려요.","43쪽 도움말이에요.","부드럽게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#2','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C2',1,'mc','auto','「이 느림보 거북아!」를 들은 거북의 기분은?',ARRAY['K2-2-u2-X03','K2-2-u2-X02']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"「이 느림보 거북아!」를 들은 거북의 기분은?","options":[{"t":"존중받지 못해서 기분이 나빠요","correct":true},{"t":"칭찬받아서 기뻐요","mis":"K2-2-u2-X03"},{"t":"장난이라서 아무렇지 않아요","mis":"K2-2-u2-X02"}],"explanation":["놀리는 말이에요.","기분이 상해요.","41쪽이에요."],"asset":{"type":"speech","turns":[{"who":"토끼","text":"이 느림보 거북아, 넌 느려서 정말 답답해!"},{"who":"거북","text":"이 까불이 토끼야! 촐랑대는 너를 보면 정말 짜증 나!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#3','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C3',1,'mc','auto','고운 말로 대화하는 방법으로 알맞은 것은?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":3,"concept":"K2-2-u2-C3","difficulty":1,"kind":"mc","stem":"고운 말로 대화하는 방법으로 알맞은 것은?","options":[{"t":"욕설이나 비속어를 사용하지 않아요","correct":true},{"t":"기분이 좋으면 무조건 크게 말해요","mis":"K2-2-u2-X05"},{"t":"친한 친구에게는 비속어를 써요","mis":"K2-2-u2-X05"}],"explanation":["욕설·비속어는 쓰지 않아요.","47쪽 정리예요.","누구에게나 그래요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#4','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C4',1,'mc','auto','「학교 다녀오겠습니다.」에 알맞은 대답은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":4,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"「학교 다녀오겠습니다.」에 알맞은 대답은?","options":[{"t":"조심히 다녀오렴.","correct":true},{"t":"그동안 고마웠어.","mis":"K2-2-u2-X01"},{"t":"생일 축하해.","mis":"K2-2-u2-X01"}],"explanation":["인사에 어울려요.","49쪽 그림 가예요.","상황을 살펴요."],"asset":{"type":"passage","lines":["가: 「학교 다녀오겠습니다.」 — 「조심히 다녀오렴.」","나: 「점심시간에 나랑 축구할래?」 — 「좋아! 오늘도 재미있게 놀자.」","다: 「잘 있어. 그동안 고마웠어.」 — 「너와 헤어져서 아쉬워. 앞으로 자주 연락하자.」"],"title":"『국어』 49쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#5','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C5',1,'mc','auto','「상대가 잘하는 점이나 노력하는 점, 좋은 점 등을 높이 평가해 주는 것」은?',ARRAY['K2-2-u2-X08']::text[],false,'{"seq":5,"concept":"K2-2-u2-C5","difficulty":1,"kind":"mc","stem":"「상대가 잘하는 점이나 노력하는 점, 좋은 점 등을 높이 평가해 주는 것」은?","options":[{"t":"칭찬","correct":true},{"t":"조언","mis":"K2-2-u2-X08"},{"t":"사과","mis":"K2-2-u2-X08"}],"explanation":["칭찬이에요.","54쪽 도움말이에요.","좋은 점을 높이 평가해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#6','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C8',1,'mc','auto','『국어』 60쪽 — 진아가 말할 때 선우는 어떻게 반응했나요?',ARRAY['K2-2-u2-X14','K2-2-u2-X03']::text[],false,'{"seq":6,"concept":"K2-2-u2-C8","difficulty":1,"kind":"mc","stem":"『국어』 60쪽 — 진아가 말할 때 선우는 어떻게 반응했나요?","options":[{"t":"휴대 전화만 쳐다보면서 건성으로 대답했어요","correct":true},{"t":"진아를 바라보며 고개를 끄덕였어요","mis":"K2-2-u2-X14"},{"t":"진아와 미끄럼틀을 탔어요","mis":"K2-2-u2-X03"}],"explanation":["휴대 전화만 봤어요.","60쪽 예시 답안이에요.","만화를 읽어요."],"asset":{"type":"speech","turns":[{"who":"진아","text":"선우야, 우리 뭐 하고 놀까? 미끄럼틀 탈까?"},{"who":"선우","text":"(휴대 전화를 보며) 진아야, 잠깐만. 이것만 좀 하고……."},{"who":"진아","text":"아니면 술래잡기할까?"},{"who":"선우","text":"어……. 어……."},{"who":"진아","text":"선우야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#7','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C9',1,'mc','auto','『국어』 68쪽 — 낱말을 맞게 쓴 문장은?',ARRAY['K2-2-u2-X16']::text[],false,'{"seq":7,"concept":"K2-2-u2-C9","difficulty":1,"kind":"mc","stem":"『국어』 68쪽 — 낱말을 맞게 쓴 문장은?","options":[{"t":"어머니께서 동생을 안고 있다.","correct":true},{"t":"어머니께서 동생을 앉고 있다.","mis":"K2-2-u2-X16"},{"t":"어머니께서 동생을 않고 있다.","mis":"K2-2-u2-X16"}],"explanation":["품에 안는 것은 「안다」.","68쪽이에요.","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#8','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C10',1,'mc','auto','『국어』 64쪽 「이런 활동 어때요」에 나온 활동은?',ARRAY['K2-2-u2-X17']::text[],false,'{"seq":8,"concept":"K2-2-u2-C10","difficulty":1,"kind":"mc","stem":"『국어』 64쪽 「이런 활동 어때요」에 나온 활동은?","options":[{"t":"알림판에 칭찬이나 조언 쪽지 붙이기","correct":true},{"t":"노래 자랑하기","mis":"K2-2-u2-X17"},{"t":"교실 대청소하기","mis":"K2-2-u2-X17"}],"explanation":["알림판 쪽지예요.","64쪽이에요.","실천 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#9','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C2',2,'mc','auto','『국어』 45쪽 — 민서와 대화했을 때 하늘이의 기분은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":9,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 — 민서와 대화했을 때 하늘이의 기분은?","options":[{"t":"민서가 말을 잘 듣고 공감해 주어 기분이 좋았을 것 같아요","correct":true},{"t":"민서가 짜증을 내서 속상했을 것 같아요","mis":"K2-2-u2-X03"},{"t":"민서가 대답하지 않아서 서운했을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["「좋은 생각이야.」","공감해 주었어요.","45쪽이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#10','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C4',2,'mc','auto','다리를 다친 친구가 「운동장에 나가고 싶어.」라고 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"다리를 다친 친구가 「운동장에 나가고 싶어.」라고 해요. 알맞은 고운 말은?","options":[{"t":"다리를 다쳐서 힘들지? 내가 문을 열어 줄게.","correct":true},{"t":"다리도 아픈데 왜 나가?","mis":"K2-2-u2-X02"},{"t":"혼자 알아서 해.","mis":"K2-2-u2-X02"}],"explanation":["처지를 헤아려요.","도와줘요.","50쪽 그림 가예요."],"asset":{"type":"scene","icon":"🩼🚪🧒","text":"『국어』 50쪽 그림 가 — 다리를 다쳐 목발을 짚은 친구가 운동장에 나가고 싶어 해요. 문을 여닫기가 불편해요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#11','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C6',2,'match','auto','『국어』 55쪽 — 칭찬하는 말과 칭찬하는 방법을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u2-C6","difficulty":2,"kind":"match","stem":"『국어』 55쪽 — 칭찬하는 말과 칭찬하는 방법을 이어 보세요.","pairs":[{"l":"미술 작품을 완성하려고 끝까지 노력하는 네가 정말 대단해.","r":"열심히 노력하는 점을 찾아 칭찬해요"},{"l":"처음 보는 옷이네. 너한테 어울리는 색으로 잘 골랐다.","r":"좋은 점을 너무 부풀리지 않고 진심으로 칭찬해요"},{"l":"너는 참 친절해. 내가 궁금한 것을 물어보면 늘 잘 알려 줘.","r":"칭찬하는 점과 그 까닭이 드러나게 이야기해요"}],"mis":"K2-2-u2-X09","explanation":["노력 · 진심 · 까닭이에요.","55쪽 예시 답안이에요.","붙임딱지 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#12','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C4',2,'ox','auto','고운 말을 쓴다는 것은 무조건 친구의 의견에 찬성하는 거예요.',ARRAY['K2-2-u2-X04']::text[],false,'{"seq":12,"concept":"K2-2-u2-C4","difficulty":2,"kind":"ox","stem":"고운 말을 쓴다는 것은 무조건 친구의 의견에 찬성하는 거예요.","answer":"X","reason_options":[{"t":"다른 의견도 상대의 기분이 상하지 않게 말할 수 있으니까","correct":true},{"t":"다른 의견은 말하면 안 되니까","mis":"K2-2-u2-X04"}],"mis":"K2-2-u2-X04","explanation":["찬성만이 아니에요.","다른 의견도 고운 말로요.","지도서 101쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#13','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C6',2,'mc','auto','「작품이 이상하기는 하지만 끝까지 열심히 완성하기는 했네.」는 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X09']::text[],false,'{"seq":13,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"「작품이 이상하기는 하지만 끝까지 열심히 완성하기는 했네.」는 무엇이 아쉬운가요?","options":[{"t":"잘못한 점과 함께 말해 칭찬으로 느껴지지 않아요","correct":true},{"t":"까닭을 너무 자세히 말했어요","mis":"K2-2-u2-X09"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X09"}],"explanation":["잘못한 점을 함께 말했어요.","지도서 110쪽이에요.","잘한 점만 진심으로요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"작품이 이상하기는 하지만 끝까지 열심히 완성하기는 했네."},{"who":"친구 2","text":"작품이 이상하다니……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#14','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C7',2,'mc','auto','「넌 왜 그렇게 게으르니? 제대로 정리 좀 해!」는 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X12','K2-2-u2-X11']::text[],false,'{"seq":14,"concept":"K2-2-u2-C7","difficulty":2,"kind":"mc","stem":"「넌 왜 그렇게 게으르니? 제대로 정리 좀 해!」는 무엇이 아쉬운가요?","options":[{"t":"상대를 비난하며 명령하듯 말해 위하는 마음이 느껴지지 않아요","correct":true},{"t":"해결 방법을 너무 자세히 알려 주었어요","mis":"K2-2-u2-X12"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X11"}],"explanation":["비난하며 지시했어요.","지도서 112쪽이에요.","걱정하는 마음을 담아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"정리할 게 너무 많아. 귀찮으니까 정리하지 말고 사물함에 다 넣어야겠어."},{"who":"친구 2","text":"넌 왜 그렇게 게으르니? 제대로 정리 좀 해!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
