INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#20','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C4',3,'mc','auto','정현이의 「아, 짜증 나! 나는 보드게임이 더 재미있단 말이야.」를 고운 말로 바꾼 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":20,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"정현이의 「아, 짜증 나! 나는 보드게임이 더 재미있단 말이야.」를 고운 말로 바꾼 것은?","options":[{"t":"나는 보드게임이 하고 싶지만 지금은 네 의견을 따를게. 다음 쉬는 시간에는 보드게임하자!","correct":true},{"t":"됐어, 너희끼리 해.","mis":"K2-2-u2-X02"},{"t":"쌓기 놀이는 시시해.","mis":"K2-2-u2-X02"}],"explanation":["내 생각을 고운 말로요.","45쪽 예시 답안이에요.","찬성만이 고운 말은 아니에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#21','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C7',3,'mc','auto','『국어』 67쪽 — 「책이 자꾸 쓰러져 사물함 정리가 어려운데 좋은 방법이 없을까?」에 바른 조언은?',ARRAY['K2-2-u2-X11','K2-2-u2-X12']::text[],false,'{"seq":21,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"『국어』 67쪽 — 「책이 자꾸 쓰러져 사물함 정리가 어려운데 좋은 방법이 없을까?」에 바른 조언은?","options":[{"t":"책꽂이를 사용하면 잘 정리할 수 있어.","correct":true},{"t":"네가 정리를 못 하니까 그렇지.","mis":"K2-2-u2-X11"},{"t":"그냥 다 버려.","mis":"K2-2-u2-X12"}],"explanation":["해결 방법을 알려 주었어요.","67쪽 3번이에요.","도우려는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#22','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C8',3,'mc','auto','「어젯밤에 무서운 꿈을…….」에 적절하게 반응한 것은?',ARRAY['K2-2-u2-X15']::text[],false,'{"seq":22,"concept":"K2-2-u2-C8","difficulty":3,"kind":"mc","stem":"「어젯밤에 무서운 꿈을…….」에 적절하게 반응한 것은?","options":[{"t":"끝까지 들은 뒤 「무서운 꿈을 꿔서 많이 놀랐겠다. 무슨 꿈이었어?」","correct":true},{"t":"「야, 꿈인데 뭐가 무섭다고 그래?」","mis":"K2-2-u2-X15"},{"t":"말을 끊고 「나도 어제 꿈꿨어!」","mis":"K2-2-u2-X15"}],"explanation":["끝까지 들어요.","공감해요.","61쪽 그림 다예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"어젯밤에 무서운 꿈을……."},{"who":"친구 2","text":"야, 꿈인데 뭐가 무섭다고 그래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#23','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C1',4,'sa','auto','「다른 사람의 마음을 헤아려서 부드럽게 하는 말」을 무엇이라고 하나요?','{}'::text[],false,'{"seq":23,"concept":"K2-2-u2-C1","difficulty":4,"kind":"sa","stem":"「다른 사람의 마음을 헤아려서 부드럽게 하는 말」을 무엇이라고 하나요?","answer":["고운 말","고운말"],"explanation":["고운 말이에요.","43쪽이에요.","마음을 헤아려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#24','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C4',4,'essay','teacher','지도서 127쪽 평가 — 친구가 「오늘 점심 정말 맛있다. 하나도 남기지 않고 다 먹었어.」라고 해요. 알맞은 고운 말로 대답을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"지도서 127쪽 평가 — 친구가 「오늘 점심 정말 맛있다. 하나도 남기지 않고 다 먹었어.」라고 해요. 알맞은 고운 말로 대답을 쓰세요.","answer_guide":{"answer":"예: 우아, 골고루 다 먹다니 정말 대단하다! 나도 너처럼 남기지 않고 먹어 볼게.","scoring_points":["친구의 말에 어울리는 대답이에요","고운 말을 썼어요","상대의 기분을 생각했어요"]},"explanation":["상황을 먼저 살펴요.","고운 말로 대답해요.","지도서 127쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"오늘 점심 정말 맛있다. 하나도 남기지 않고 다 먹었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_a#25','kor',2,2,'u2','','g2_2_kor_u2_review_a','unit_review','K2-2-u2-C7',4,'essay','teacher','지도서 129쪽 평가 — 내가 조언을 구하고 싶은 내용과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u2-C7","difficulty":4,"kind":"essay","stem":"지도서 129쪽 평가 — 내가 조언을 구하고 싶은 내용과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 조언을 구하고 싶은 내용: 아침에 일찍 일어나는 방법 / 까닭: 늦잠을 자서 학교에 급하게 오는 날이 많아요.","scoring_points":["조언을 구하고 싶은 내용이 있어요","까닭이 있어요"]},"explanation":["내 고민을 떠올려요.","까닭을 함께 써요.","지도서 129쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#1','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C1',1,'mc','auto','고운 말인 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":1,"concept":"K2-2-u2-C1","difficulty":1,"kind":"mc","stem":"고운 말인 것은?","options":[{"t":"고마워.","correct":true},{"t":"짜증 나!","mis":"K2-2-u2-X02"},{"t":"됐거든.","mis":"K2-2-u2-X02"}],"explanation":["「고마워.」는 고운 말이에요.","듣는 사람이 기분 좋아요.","43쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#2','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C2',1,'mc','auto','「노력하는 네 모습은 정말 대단해!」를 들은 거북의 기분은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"「노력하는 네 모습은 정말 대단해!」를 들은 거북의 기분은?","options":[{"t":"칭찬을 받아서 기분이 좋아요","correct":true},{"t":"놀림을 받아서 속상해요","mis":"K2-2-u2-X03"},{"t":"화가 나요","mis":"K2-2-u2-X03"}],"explanation":["노력을 알아봐 주었어요.","기분이 좋아요.","41쪽이에요."],"asset":{"type":"speech","turns":[{"who":"토끼","text":"거북아, 빠르게 달리려고 노력하는 네 모습은 정말 대단해!"},{"who":"거북","text":"고마워, 토끼야. 너는 정말 달리기를 잘하더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#3','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C3',1,'mc','auto','고운 말로 대화하는 방법으로 알맞은 것은?',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":3,"concept":"K2-2-u2-C3","difficulty":1,"kind":"mc","stem":"고운 말로 대화하는 방법으로 알맞은 것은?","options":[{"t":"상대의 기분이 상하지 않도록 말해요","correct":true},{"t":"말하는 사람의 상황만 생각해요","mis":"K2-2-u2-X05"},{"t":"하고 싶은 말을 생각나는 대로 해요","mis":"K2-2-u2-X05"}],"explanation":["상대의 기분을 살펴요.","47쪽 정리예요.","국어활동 26쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#4','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C4',1,'mc','auto','「점심시간에 나랑 축구할래?」에 알맞은 대답은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":4,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"「점심시간에 나랑 축구할래?」에 알맞은 대답은?","options":[{"t":"좋아! 오늘도 재미있게 놀자.","correct":true},{"t":"조심히 다녀오렴.","mis":"K2-2-u2-X01"},{"t":"앞으로 자주 연락하자.","mis":"K2-2-u2-X01"}],"explanation":["놀자는 말에 대답해요.","49쪽 그림 나예요.","상황을 살펴요."],"asset":{"type":"passage","lines":["가: 「학교 다녀오겠습니다.」 — 「조심히 다녀오렴.」","나: 「점심시간에 나랑 축구할래?」 — 「좋아! 오늘도 재미있게 놀자.」","다: 「잘 있어. 그동안 고마웠어.」 — 「너와 헤어져서 아쉬워. 앞으로 자주 연락하자.」"],"title":"『국어』 49쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#5','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C5',1,'mc','auto','「다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것」은?',ARRAY['K2-2-u2-X08']::text[],false,'{"seq":5,"concept":"K2-2-u2-C5","difficulty":1,"kind":"mc","stem":"「다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것」은?","options":[{"t":"조언","correct":true},{"t":"칭찬","mis":"K2-2-u2-X08"},{"t":"인사","mis":"K2-2-u2-X08"}],"explanation":["조언이에요.","54쪽 도움말이에요.","어려움을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#6','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C2',1,'mc','auto','『국어』 60쪽 — 선우의 반응을 본 진아의 기분은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":6,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 60쪽 — 선우의 반응을 본 진아의 기분은?","options":[{"t":"서운했을 것 같아요","correct":true},{"t":"신났을 것 같아요","mis":"K2-2-u2-X03"},{"t":"편안했을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["서운하거나 화가 났을 거예요.","60쪽 예시 답안이에요.","반응이 기분을 바꿔요."],"asset":{"type":"speech","turns":[{"who":"진아","text":"선우야, 우리 뭐 하고 놀까? 미끄럼틀 탈까?"},{"who":"선우","text":"(휴대 전화를 보며) 진아야, 잠깐만. 이것만 좀 하고……."},{"who":"진아","text":"아니면 술래잡기할까?"},{"who":"선우","text":"어……. 어……."},{"who":"진아","text":"선우야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
