INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#8','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C10',1,'mc','auto','「칭찬합시다」 알림판 쪽지에 쓸 것은?',ARRAY['K2-2-u2-X11','K2-2-u2-X17']::text[],false,'{"seq":8,"concept":"K2-2-u2-C10","difficulty":1,"kind":"mc","stem":"「칭찬합시다」 알림판 쪽지에 쓸 것은?","options":[{"t":"칭찬하고 싶은 친구의 이름과 칭찬하는 내용","correct":true},{"t":"친구가 잘못한 일","mis":"K2-2-u2-X11"},{"t":"내 이름만","mis":"K2-2-u2-X17"}],"explanation":["이름과 내용을 써요.","64쪽 ①이에요.","까닭도 드러나게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#9','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C2',2,'mc','auto','『국어』 45쪽 — 정현이의 말을 들었을 때 하늘이의 기분은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":9,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 — 정현이의 말을 들었을 때 하늘이의 기분은?","options":[{"t":"정현이가 짜증을 내며 말해 당황스러웠을 것 같아요","correct":true},{"t":"칭찬받아 뿌듯했을 것 같아요","mis":"K2-2-u2-X03"},{"t":"신났을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["「짜증 나!」","당황했을 거예요.","45쪽이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#10','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C4',2,'mc','auto','늦게 온 친구가 「내가 늦었지?」라고 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02','K2-2-u2-X04']::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"늦게 온 친구가 「내가 늦었지?」라고 해요. 알맞은 고운 말은?","options":[{"t":"기다리느라 힘들었어. 다음부터는 좀 일찍 오면 좋겠어.","correct":true},{"t":"너랑 다시는 안 놀아!","mis":"K2-2-u2-X02"},{"t":"괜찮아, 다음에도 늦어도 돼.","mis":"K2-2-u2-X04"}],"explanation":["솔직하되 부드럽게요.","바라는 점을 말해요.","50쪽 그림 나예요."],"asset":{"type":"scene","icon":"⏰🧒🧒","text":"『국어』 50쪽 그림 나 — 친구가 약속 시간을 지키지 못하고 늦게 와서 승훈이가 한참을 기다렸어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#11','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C7',2,'match','auto','『국어』 56쪽 — 조언하는 말과 조언하는 방법을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u2-C7","difficulty":2,"kind":"match","stem":"『국어』 56쪽 — 조언하는 말과 조언하는 방법을 이어 보세요.","pairs":[{"l":"물건이 쏟아져 다칠 수도 있어. 정리해서 넣어 두는 게 어때?","r":"걱정하는 마음을 담아 고치면 좋을 습관을 알려 줘요"},{"l":"날마다 10분씩 줄넘기 연습을 해 보면 어떨까?","r":"문제를 해결할 수 있는 방법을 말해 줘요"},{"l":"실수는 누구나 하는 거니까 너무 실망하지 마.","r":"듣는 사람의 마음에 공감하며 격려해 줘요"}],"mis":"K2-2-u2-X12","explanation":["걱정 · 방법 · 격려예요.","56쪽 예시 답안이에요.","붙임딱지 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#12','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C3',2,'ox','auto','친한 친구에게는 비속어를 써도 괜찮아요.',ARRAY['K2-2-u2-X05']::text[],false,'{"seq":12,"concept":"K2-2-u2-C3","difficulty":2,"kind":"ox","stem":"친한 친구에게는 비속어를 써도 괜찮아요.","answer":"X","reason_options":[{"t":"비속어는 상대를 낮추어 보는 말이라 누구에게도 쓰지 않으니까","correct":true},{"t":"친한 사이에서는 장난이니까","mis":"K2-2-u2-X05"}],"mis":"K2-2-u2-X05","explanation":["누구에게도 쓰지 않아요.","47쪽 도움말이에요.","국어활동 26쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#13','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C6',2,'mc','auto','「처음 보는 옷이네. 세상에서 네가 가장 멋져.」는 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X09']::text[],false,'{"seq":13,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"「처음 보는 옷이네. 세상에서 네가 가장 멋져.」는 무엇이 아쉬운가요?","options":[{"t":"너무 부풀려서 칭찬해 진심으로 느껴지지 않아요","correct":true},{"t":"잘못한 점과 함께 말했어요","mis":"K2-2-u2-X09"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X09"}],"explanation":["너무 부풀렸어요.","지도서 110쪽이에요.","진심으로 칭찬해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"처음 보는 옷이네. 세상에서 네가 가장 멋져."},{"who":"친구 2","text":"세상에서 가장 멋지기까지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#14','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C7',2,'mc','auto','「그냥 하면 돼.」는 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X08','K2-2-u2-X12']::text[],false,'{"seq":14,"concept":"K2-2-u2-C7","difficulty":2,"kind":"mc","stem":"「그냥 하면 돼.」는 무엇이 아쉬운가요?","options":[{"t":"구체적인 해결 방법을 알려 주지 않아 성의 없어 보여요","correct":true},{"t":"상대를 너무 칭찬했어요","mis":"K2-2-u2-X08"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X12"}],"explanation":["방법이 없어요.","지도서 112쪽이에요.","방법을 알려 줘요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나도 너처럼 줄넘기를 잘하고 싶은데……."},{"who":"친구 2","text":"그냥 하면 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
