INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#20','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C4',3,'mc','auto','『국어활동』 28쪽 — 친구가 「왜 이렇게 안 끼워지지?」 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02','K2-2-u2-X05']::text[],false,'{"seq":20,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어활동』 28쪽 — 친구가 「왜 이렇게 안 끼워지지?」 해요. 알맞은 고운 말은?","options":[{"t":"내가 도와줄게. 같이 만들자.","correct":true},{"t":"그것도 못 해?","mis":"K2-2-u2-X02"},{"t":"나는 바빠.","mis":"K2-2-u2-X05"}],"explanation":["어려운 친구를 도와요.","국어활동 28쪽이에요.","고운 말로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#21','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C7',3,'mc','auto','지도서 124쪽 — 조언할 때 문제 해결 방법을 알려 주기 전에 먼저 하면 좋은 말은?',ARRAY['K2-2-u2-X11','K2-2-u2-X13']::text[],false,'{"seq":21,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"지도서 124쪽 — 조언할 때 문제 해결 방법을 알려 주기 전에 먼저 하면 좋은 말은?","options":[{"t":"「많이 힘드니?」처럼 상대의 상태를 확인하고 걱정해 주는 말","correct":true},{"t":"「너 때문이야.」처럼 잘못을 따지는 말","mis":"K2-2-u2-X11"},{"t":"「그건 누구나 그래.」처럼 넘기는 말","mis":"K2-2-u2-X13"}],"explanation":["먼저 상태를 살펴요.","걱정하는 마음을 표현해요.","지도서 124쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#22','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C8',3,'mc','auto','「나 이제 두발자전거를 혼자 탈 수 있게 됐어!」에 적절하게 반응한 것은?',ARRAY['K2-2-u2-X14','K2-2-u2-X02']::text[],false,'{"seq":22,"concept":"K2-2-u2-C8","difficulty":3,"kind":"mc","stem":"「나 이제 두발자전거를 혼자 탈 수 있게 됐어!」에 적절하게 반응한 것은?","options":[{"t":"바라보며 웃는 얼굴로 「우아, 정말 잘됐다! 연습 많이 했구나.」","correct":true},{"t":"다른 곳을 보며 「오늘 오후에 뭐 하고 놀지?」","mis":"K2-2-u2-X14"},{"t":"「그게 뭐 대단해?」","mis":"K2-2-u2-X02"}],"explanation":["바라보며 웃어요.","기쁨에 공감해요.","61쪽 그림 가예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나 이제 두발자전거를 혼자 탈 수 있게 됐어!"},{"who":"친구 2","text":"(다른 곳을 보며) 오늘 오후에 뭐 하고 놀지?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#23','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C3',4,'sa','auto','「다른 사람의 생각과 마음에 대하여 자신도 그렇게 느끼는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u2-C3","difficulty":4,"kind":"sa","stem":"「다른 사람의 생각과 마음에 대하여 자신도 그렇게 느끼는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["공감"],"explanation":["공감이에요.","46쪽이에요.","마음을 같이 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#24','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C4',4,'essay','teacher','『국어활동』 29쪽 가 — 늦게 온 친구가 「내가 너무 늦었지? 얘들아, 미안해.」라고 해요. 고운 말로 대답을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"『국어활동』 29쪽 가 — 늦게 온 친구가 「내가 너무 늦었지? 얘들아, 미안해.」라고 해요. 고운 말로 대답을 쓰세요.","answer_guide":{"answer":"예: 괜찮아. 우리도 조금 전에 왔어. / 네가 늦어서 걱정했어. 다음부터는 약속 시간을 잘 지키면 좋겠어.","scoring_points":["상황에 어울리는 대답이에요","고운 말을 썼어요"]},"explanation":["사과를 받아 줘요.","바라는 점도 부드럽게요.","국어활동 29쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_b#25','kor',2,2,'u2','','g2_2_kor_u2_review_b','unit_review','K2-2-u2-C7',4,'essay','teacher','친구가 「나도 너처럼 줄넘기를 잘하고 싶은데…….」라고 해요. 먼저 친구의 마음에 공감하는 말을 하고, 해결 방법을 알려 주는 조언을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u2-C7","difficulty":4,"kind":"essay","stem":"친구가 「나도 너처럼 줄넘기를 잘하고 싶은데…….」라고 해요. 먼저 친구의 마음에 공감하는 말을 하고, 해결 방법을 알려 주는 조언을 쓰세요.","answer_guide":{"answer":"예: 줄넘기를 잘하고 싶구나. 날마다 10분씩 꾸준히 연습해 보면 어떨까? 나도 같이 해 줄게.","scoring_points":["공감하는 말이 있어요","해결 방법이 있어요","부드러운 말투예요"]},"explanation":["먼저 마음을 알아줘요.","방법을 알려 줘요.","지도서 129쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나도 너처럼 줄넘기를 잘하고 싶은데……."},{"who":"친구 2","text":"그냥 하면 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#1','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C1',1,'mc','auto','『국어활동』 27쪽 — 고운 말로 대화한 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":1,"concept":"K2-2-u2-C1","difficulty":1,"kind":"mc","stem":"『국어활동』 27쪽 — 고운 말로 대화한 것은?","options":[{"t":"「경기에 져서 속상해.」 — 「괜찮아, 다음에 또 잘하면 돼. 힘내자.」","correct":true},{"t":"「경기에 져서 속상해.」 — 「됐거든, 너 때문에 진 거야!」","mis":"K2-2-u2-X02"},{"t":"「내 지우개 찾았다!」 — 「에구, 이 덜렁이.」","mis":"K2-2-u2-X02"}],"explanation":["속상한 친구를 위로했어요.","국어활동 27쪽이에요.","고운 말로 대답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#2','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C2',1,'mc','auto','『국어』 44쪽 — 하늘이가 친구들에게 같이 하자고 한 놀이는?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 44쪽 — 하늘이가 친구들에게 같이 하자고 한 놀이는?","options":[{"t":"쌓기 놀이","correct":true},{"t":"보드게임","mis":"K2-2-u2-X03"},{"t":"줄넘기","mis":"K2-2-u2-X03"}],"explanation":["쌓기 놀이예요.","44쪽이에요.","대화를 읽어요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#3','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C3',1,'mc','auto','고운 말로 대화하는 방법으로 알맞은 것은?',ARRAY['K2-2-u2-X05','K2-2-u2-X14']::text[],false,'{"seq":3,"concept":"K2-2-u2-C3","difficulty":1,"kind":"mc","stem":"고운 말로 대화하는 방법으로 알맞은 것은?","options":[{"t":"친구의 말을 잘 듣고 상황에 알맞은 말을 해요","correct":true},{"t":"친구의 말을 듣지 않고 내 말만 해요","mis":"K2-2-u2-X05"},{"t":"친구가 말할 때 딴생각을 해요","mis":"K2-2-u2-X14"}],"explanation":["잘 듣고 말해요.","47쪽 정리예요.","상황에 알맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#4','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C4',1,'mc','auto','「잘 있어. 그동안 고마웠어.」에 알맞은 대답은?',ARRAY['K2-2-u2-X01']::text[],false,'{"seq":4,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"「잘 있어. 그동안 고마웠어.」에 알맞은 대답은?","options":[{"t":"너와 헤어져서 아쉬워. 앞으로 자주 연락하자.","correct":true},{"t":"좋아! 오늘도 재미있게 놀자.","mis":"K2-2-u2-X01"},{"t":"수고했어.","mis":"K2-2-u2-X01"}],"explanation":["헤어지는 상황이에요.","49쪽 그림 다예요.","아쉬운 마음을 말해요."],"asset":{"type":"passage","lines":["가: 「학교 다녀오겠습니다.」 — 「조심히 다녀오렴.」","나: 「점심시간에 나랑 축구할래?」 — 「좋아! 오늘도 재미있게 놀자.」","다: 「잘 있어. 그동안 고마웠어.」 — 「너와 헤어져서 아쉬워. 앞으로 자주 연락하자.」"],"title":"『국어』 49쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#5','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C5',1,'mc','auto','속삭이가 크니프에게 한 「너는 목소리가 커서 멋있는걸.」은 무엇인가요?',ARRAY['K2-2-u2-X08']::text[],false,'{"seq":5,"concept":"K2-2-u2-C5","difficulty":1,"kind":"mc","stem":"속삭이가 크니프에게 한 「너는 목소리가 커서 멋있는걸.」은 무엇인가요?","options":[{"t":"칭찬","correct":true},{"t":"조언","mis":"K2-2-u2-X08"},{"t":"사과","mis":"K2-2-u2-X08"}],"explanation":["좋은 점을 말했어요.","칭찬이에요.","54쪽이에요."],"asset":{"type":"speech","turns":[{"who":"크니프","text":"너는 목소리가 참 예쁘구나. 정말 좋겠다."},{"who":"속삭이","text":"너는 목소리가 커서 멋있는걸."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#6','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C8',1,'mc','auto','대화할 때 적절히 반응하는 방법은?',ARRAY['K2-2-u2-X14','K2-2-u2-X15']::text[],false,'{"seq":6,"concept":"K2-2-u2-C8","difficulty":1,"kind":"mc","stem":"대화할 때 적절히 반응하는 방법은?","options":[{"t":"말하는 사람을 쳐다보며 대화 내용에 집중해요","correct":true},{"t":"급한 일을 하면서 들어요","mis":"K2-2-u2-X14"},{"t":"무조건 큰 소리로 반응해요","mis":"K2-2-u2-X15"}],"explanation":["쳐다보며 집중해요.","62쪽이에요.","국어활동 31쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
