INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#8','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C10',1,'mc','auto','「조언을 구해요」 알림판에 붙이는 것은?',ARRAY['K2-2-u2-X08','K2-2-u2-X17']::text[],false,'{"seq":8,"concept":"K2-2-u2-C10","difficulty":1,"kind":"mc","stem":"「조언을 구해요」 알림판에 붙이는 것은?","options":[{"t":"조언을 구하고 싶은 고민","correct":true},{"t":"칭찬 쪽지","mis":"K2-2-u2-X08"},{"t":"그림일기","mis":"K2-2-u2-X17"}],"explanation":["고민을 붙여요.","64쪽 ②예요.","친구들이 조언해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#9','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C2',2,'mc','auto','『국어』 45쪽 — 하영이와 대화했을 때 하늘이의 기분은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":9,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 45쪽 — 하영이와 대화했을 때 하늘이의 기분은?","options":[{"t":"자신의 말을 집중해 듣지 않아서 기분이 나빴을 것 같아요","correct":true},{"t":"공감해 주어 기뻤을 것 같아요","mis":"K2-2-u2-X03"},{"t":"칭찬받아 고마웠을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["「어……. 뭐가?」","듣지 않았어요.","45쪽이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#10','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C4',2,'mc','auto','아빠께서 「아직도 휴대 전화를 하고 있네.」 하셨어요. 알맞은 대답은?',ARRAY['K2-2-u2-X07','K2-2-u2-X14']::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"아빠께서 「아직도 휴대 전화를 하고 있네.」 하셨어요. 알맞은 대답은?","options":[{"t":"아빠, 제가 휴대 전화를 너무 오랫동안 했네요. 이제 책 읽을게요.","correct":true},{"t":"아빠는 상관하지 마세요.","mis":"K2-2-u2-X07"},{"t":"(못 들은 척한다)","mis":"K2-2-u2-X14"}],"explanation":["높임말로 대답해요.","잘못을 알고 말해요.","50쪽 그림 다예요."],"asset":{"type":"scene","icon":"📱👨👧","text":"『국어』 50쪽 그림 다 — 하교 후 휴대 전화만 보는 딸에게 아빠가 「아직도 휴대 전화를 하고 있네.」 하셨어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#11','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C8',2,'match','auto','『국어』 61쪽 — 그림과 적절하게 반응하지 못한 점을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u2-C8","difficulty":2,"kind":"match","stem":"『국어』 61쪽 — 그림과 적절하게 반응하지 못한 점을 이어 보세요.","pairs":[{"l":"그림 가 (두발자전거)","r":"쳐다보지 않고 딴생각을 해요"},{"l":"그림 나 (물통)","r":"질문에 화내듯이 답해요"},{"l":"그림 다 (무서운 꿈)","r":"말이 끝나기 전에 끼어들어 무시해요"}],"mis":"K2-2-u2-X14","explanation":["시선 · 말투 · 끝까지 듣기예요.","61쪽이에요.","지도서 117~118쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#12','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C6',2,'ox','auto','칭찬은 잘한 점을 최대한 부풀려야 진심이 전해져요.',ARRAY['K2-2-u2-X09']::text[],false,'{"seq":12,"concept":"K2-2-u2-C6","difficulty":2,"kind":"ox","stem":"칭찬은 잘한 점을 최대한 부풀려야 진심이 전해져요.","answer":"X","reason_options":[{"t":"너무 부풀리면 오히려 진심으로 느껴지지 않으니까","correct":true},{"t":"부풀릴수록 기분이 좋아지니까","mis":"K2-2-u2-X09"}],"mis":"K2-2-u2-X09","explanation":["부풀리면 안 돼요.","지도서 110쪽이에요.","국어활동 30쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#13','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C6',2,'mc','auto','「너는 참 친절해.」라고만 한 칭찬은 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X09']::text[],false,'{"seq":13,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"「너는 참 친절해.」라고만 한 칭찬은 무엇이 아쉬운가요?","options":[{"t":"칭찬하는 까닭을 말하지 않아 진심으로 느껴지지 않을 수 있어요","correct":true},{"t":"너무 부풀려서 칭찬했어요","mis":"K2-2-u2-X09"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X09"}],"explanation":["까닭이 빠졌어요.","지도서 110쪽이에요.","까닭과 함께 말해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"너는 참 친절해."},{"who":"친구 2","text":"왜 그렇게 생각하는 걸까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#14','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C7',2,'mc','auto','「야, 뭐 그런 일로 고민해? 누구나 다 그래.」는 무엇이 아쉬운가요?',ARRAY['K2-2-u2-X12','K2-2-u2-X13']::text[],false,'{"seq":14,"concept":"K2-2-u2-C7","difficulty":2,"kind":"mc","stem":"「야, 뭐 그런 일로 고민해? 누구나 다 그래.」는 무엇이 아쉬운가요?","options":[{"t":"상대를 무시하듯 말해 존중받지 못한다고 느낄 수 있어요","correct":true},{"t":"해결 방법을 너무 많이 알려 주었어요","mis":"K2-2-u2-X12"},{"t":"아쉬운 점이 없어요","mis":"K2-2-u2-X13"}],"explanation":["무시하듯 말했어요.","지도서 112쪽이에요.","마음을 먼저 알아줘요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 왜 자꾸 실수하는 걸까? 실수하지 않으려면 어떻게 해야 할까?"},{"who":"친구 2","text":"야, 뭐 그런 일로 고민해? 누구나 다 그래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
