INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#20','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C4',3,'mc','auto','『국어활동』 28쪽 — 숙제를 해야 하는데 친구가 「같이 그림 그리러 가자.」 해요. 알맞은 고운 말은?',ARRAY['K2-2-u2-X02','K2-2-u2-X04']::text[],false,'{"seq":20,"concept":"K2-2-u2-C4","difficulty":3,"kind":"mc","stem":"『국어활동』 28쪽 — 숙제를 해야 하는데 친구가 「같이 그림 그리러 가자.」 해요. 알맞은 고운 말은?","options":[{"t":"미안해. 나 지금 숙제해야 해. 다음에 같이 놀자.","correct":true},{"t":"싫어, 저리 가.","mis":"K2-2-u2-X02"},{"t":"알았어. (숙제를 그만두고 따라간다)","mis":"K2-2-u2-X04"}],"explanation":["거절도 고운 말로 해요.","국어활동 28쪽이에요.","다음을 약속해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#21','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C7',3,'mc','auto','「밤에 자려고 누우면 무서운 생각이 들 때가 많아요.」에 알맞은 조언은?',ARRAY['K2-2-u2-X11','K2-2-u2-X13']::text[],false,'{"seq":21,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"「밤에 자려고 누우면 무서운 생각이 들 때가 많아요.」에 알맞은 조언은?","options":[{"t":"좋아하는 물건을 머리맡에 두고 자는 건 어때?","correct":true},{"t":"겁쟁이처럼 굴지 마.","mis":"K2-2-u2-X11"},{"t":"그런 걸로 왜 고민해?","mis":"K2-2-u2-X13"}],"explanation":["방법을 알려 주었어요.","64쪽 쪽지예요.","부드럽게 말했어요."],"asset":{"type":"passage","lines":["칭찬합시다 ① 평소 고운 말을 잘 쓰는 서율이를 칭찬합니다.","칭찬합시다 ② 음식을 남기지 않고 골고루 잘 먹는 지훈이를 칭찬합니다.","칭찬합시다 ③ 무거운 짐을 같이 들어 준 하린이를 칭찬합니다.","조언을 구해요: 밤에 자려고 누우면 무서운 생각이 들 때가 많아요.","조언 ① 즐거웠던 일을 떠올리면 무서운 생각이 들지 않을 거야.","조언 ② 좋아하는 물건을 머리맡에 두고 자는 건 어때?","조언 ③ 자기 전에 무서운 이야기가 나오는 책은 읽지 않는 것이 좋아."],"title":"『국어』 64쪽 알림판 쪽지 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#22','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C8',3,'mc','auto','「혹시 내 물통이 어디 있는지 아니?」에 적절하게 반응한 것은?',ARRAY['K2-2-u2-X14','K2-2-u2-X06']::text[],false,'{"seq":22,"concept":"K2-2-u2-C8","difficulty":3,"kind":"mc","stem":"「혹시 내 물통이 어디 있는지 아니?」에 적절하게 반응한 것은?","options":[{"t":"물통을 잃어버려서 걱정되겠다. 같이 찾아볼까?","correct":true},{"t":"내가 그걸 어떻게 알아? 다른 친구한테 물어봐!","mis":"K2-2-u2-X14"},{"t":"물통 하나 없어도 괜찮잖아.","mis":"K2-2-u2-X06"}],"explanation":["부드러운 말투로요.","걱정하는 마음에 공감해요.","61쪽 그림 나예요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"혹시 내 물통이 어디 있는지 아니?"},{"who":"친구 2","text":"내가 그걸 어떻게 알아? 다른 친구한테 물어봐!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#23','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C5',4,'sa','auto','「다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u2-C5","difficulty":4,"kind":"sa","stem":"「다른 사람에게 어려움이 있을 때 도움이 되도록 말로 알려 주는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["조언"],"explanation":["조언이에요.","54쪽이에요.","칭찬과 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#24','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C4',4,'essay','teacher','『국어활동』 29쪽 나 — 친구가 「지난번 상상화 그리기 대회에서 상을 받은 그림이야.」라고 해요. 고운 말로 대답을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"『국어활동』 29쪽 나 — 친구가 「지난번 상상화 그리기 대회에서 상을 받은 그림이야.」라고 해요. 고운 말로 대답을 쓰세요.","answer_guide":{"answer":"예: 우아! 정말 멋지다. 네 그림을 보고 있으니 기분이 좋아져. / 상 받은 것 축하해.","scoring_points":["친구의 말에 어울리는 대답이에요","축하나 칭찬하는 고운 말이에요"]},"explanation":["축하하거나 칭찬해요.","고운 말로 대답해요.","국어활동 29쪽 예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_c#25','kor',2,2,'u2','','g2_2_kor_u2_review_c','unit_review','K2-2-u2-C6',4,'essay','teacher','친구 한 명을 골라 칭찬하는 말을 쓰세요. 칭찬하는 점과 그 까닭이 드러나게, 부풀리지 않고 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u2-C6","difficulty":4,"kind":"essay","stem":"친구 한 명을 골라 칭찬하는 말을 쓰세요. 칭찬하는 점과 그 까닭이 드러나게, 부풀리지 않고 쓰세요.","answer_guide":{"answer":"예: 하린아, 무거운 짐을 같이 들어 줘서 고마워. 네 덕분에 힘들지 않게 옮길 수 있었어. 너는 정말 친절해.","scoring_points":["칭찬하는 점이 있어요","까닭이 있어요","진심이 느껴져요"]},"explanation":["무엇을 칭찬할지 정해요.","까닭과 함께 써요.","55쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#1','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C1',1,'mc','auto','노래 「꽃같이 예쁜 말」에 나오는 고운 말로 알맞은 것은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":1,"concept":"K2-2-u2-C1","difficulty":1,"kind":"mc","stem":"노래 「꽃같이 예쁜 말」에 나오는 고운 말로 알맞은 것은?","options":[{"t":"수고했어","correct":true},{"t":"저리 가","mis":"K2-2-u2-X02"},{"t":"몰라","mis":"K2-2-u2-X02"}],"explanation":["「수고했어」예요.","애쓴 사람에게 해요.","지도서 97쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#2','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C2',1,'mc','auto','『국어』 44쪽 — 하영이의 「어……. 뭐가?」로 알 수 있는 것은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":2,"concept":"K2-2-u2-C2","difficulty":1,"kind":"mc","stem":"『국어』 44쪽 — 하영이의 「어……. 뭐가?」로 알 수 있는 것은?","options":[{"t":"하영이가 대화를 집중해서 듣지 않았어요","correct":true},{"t":"하영이가 하늘이 말에 찬성했어요","mis":"K2-2-u2-X03"},{"t":"하영이가 칭찬을 했어요","mis":"K2-2-u2-X03"}],"explanation":["무엇을 물었는지 몰랐어요.","듣지 않았어요.","45쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"하늘","text":"우아, 쉬는 시간이다! 우리, 쌓기 놀이 같이 하는 거 어때?"},{"who":"민서","text":"오! 좋은 생각이야. 넷이서 하면 정말 재미있거든."},{"who":"정현","text":"아, 짜증 나! 나는 쌓기 놀이보다 보드게임이 더 재미있단 말이야."},{"who":"하늘","text":"그래? 나는 보드게임하는 것도 좋아. 하영아, 너는 어때?"},{"who":"하영","text":"어……. 뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#3','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C3',1,'mc','auto','고운 말로 대화하는 방법으로 알맞은 것은?',ARRAY['K2-2-u2-X06','K2-2-u2-X14']::text[],false,'{"seq":3,"concept":"K2-2-u2-C3","difficulty":1,"kind":"mc","stem":"고운 말로 대화하는 방법으로 알맞은 것은?","options":[{"t":"상대의 말을 공감하며 들어 줘요","correct":true},{"t":"상대의 말을 무조건 따라 해요","mis":"K2-2-u2-X06"},{"t":"상대의 말을 못 들은 척해요","mis":"K2-2-u2-X14"}],"explanation":["공감하며 들어요.","47쪽 정리예요.","마음을 같이 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#4','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C4',1,'mc','auto','『국어』 66쪽 — 「안녕? 난 전학 온 정보윤이야.」에 알맞은 대답은?',ARRAY['K2-2-u2-X02','K2-2-u2-X01']::text[],false,'{"seq":4,"concept":"K2-2-u2-C4","difficulty":1,"kind":"mc","stem":"『국어』 66쪽 — 「안녕? 난 전학 온 정보윤이야.」에 알맞은 대답은?","options":[{"t":"만나서 반가워!","correct":true},{"t":"전학을 왜 왔어?","mis":"K2-2-u2-X02"},{"t":"잘 가!","mis":"K2-2-u2-X01"}],"explanation":["반갑게 맞아 줘요.","66쪽이에요.","고운 말로 인사해요."],"asset":{"type":"speech","turns":[{"who":"전학 온 친구","text":"안녕? 난 전학 온 정보윤이야."},{"who":"친구","text":"만나서 반가워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#5','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C5',1,'mc','auto','속삭이가 크니프에게 한 「친구를 만나면 먼저 반갑게 인사해 봐!」는 무엇인가요?',ARRAY['K2-2-u2-X08']::text[],false,'{"seq":5,"concept":"K2-2-u2-C5","difficulty":1,"kind":"mc","stem":"속삭이가 크니프에게 한 「친구를 만나면 먼저 반갑게 인사해 봐!」는 무엇인가요?","options":[{"t":"조언","correct":true},{"t":"칭찬","mis":"K2-2-u2-X08"},{"t":"인사","mis":"K2-2-u2-X08"}],"explanation":["어려움을 돕는 말이에요.","조언이에요.","54쪽이에요."],"asset":{"type":"speech","turns":[{"who":"크니프","text":"아무도 날 좋아하지 않아. 아무도 나랑 이야기도 하지 않고, 놀려고 하지도 않아."},{"who":"속삭이","text":"친구를 만나면 먼저 반갑게 인사해 봐!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#6','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C8',1,'mc','auto','대화할 때 적절히 반응하는 방법은?',ARRAY['K2-2-u2-X14','K2-2-u2-X15']::text[],false,'{"seq":6,"concept":"K2-2-u2-C8","difficulty":1,"kind":"mc","stem":"대화할 때 적절히 반응하는 방법은?","options":[{"t":"상대의 말에 맞장구를 쳐 줘요","correct":true},{"t":"내 기분만 생각하며 대답해요","mis":"K2-2-u2-X14"},{"t":"좋은 생각이 나면 말을 끊고 말해요","mis":"K2-2-u2-X15"}],"explanation":["맞장구를 쳐 줘요.","국어활동 31쪽이에요.","말차례도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#7','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C9',1,'mc','auto','「밥이나 집을 만들다」를 뜻하는 낱말은?',ARRAY['K2-2-u2-X16']::text[],false,'{"seq":7,"concept":"K2-2-u2-C9","difficulty":1,"kind":"mc","stem":"「밥이나 집을 만들다」를 뜻하는 낱말은?","options":[{"t":"짓다","correct":true},{"t":"짖다","mis":"K2-2-u2-X16"},{"t":"짇다","mis":"K2-2-u2-X16"}],"explanation":["짓다예요.","68쪽 사진이에요.","「지어요」로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#8','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C10',1,'mc','auto','칭찬이나 조언 책갈피에 들어갈 문구로 알맞은 것은?',ARRAY['K2-2-u2-X11','K2-2-u2-X02']::text[],false,'{"seq":8,"concept":"K2-2-u2-C10","difficulty":1,"kind":"mc","stem":"칭찬이나 조언 책갈피에 들어갈 문구로 알맞은 것은?","options":[{"t":"항상 열심히 노력하는 너는 참 대단해.","correct":true},{"t":"너는 왜 맨날 그래?","mis":"K2-2-u2-X11"},{"t":"내가 너보다 잘해.","mis":"K2-2-u2-X02"}],"explanation":["고운 말로 칭찬했어요.","지도서 123쪽이에요.","책갈피 선물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#9','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C2',2,'mc','auto','『국어』 53쪽 — 크니프가 「목소리가 참 예쁘구나.」 했을 때 속삭이의 기분은?',ARRAY['K2-2-u2-X03']::text[],false,'{"seq":9,"concept":"K2-2-u2-C2","difficulty":2,"kind":"mc","stem":"『국어』 53쪽 — 크니프가 「목소리가 참 예쁘구나.」 했을 때 속삭이의 기분은?","options":[{"t":"무척 기쁘고 고마웠을 것 같아요","correct":true},{"t":"화가 났을 것 같아요","mis":"K2-2-u2-X03"},{"t":"슬펐을 것 같아요","mis":"K2-2-u2-X03"}],"explanation":["좋은 점을 알아봐 주었어요.","53쪽 예시 답안이에요.","기쁘고 고마워요."],"asset":{"type":"speech","turns":[{"who":"크니프","text":"너는 목소리가 참 예쁘구나. 정말 좋겠다."},{"who":"속삭이","text":"너는 목소리가 커서 멋있는걸."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#10','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C4',2,'mc','auto','「내가 만든 것 어때?」에 알맞은 대답은?',ARRAY['K2-2-u2-X02']::text[],false,'{"seq":10,"concept":"K2-2-u2-C4","difficulty":2,"kind":"mc","stem":"「내가 만든 것 어때?」에 알맞은 대답은?","options":[{"t":"우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.","correct":true},{"t":"별로야.","mis":"K2-2-u2-X02"},{"t":"내가 만든 게 더 멋져.","mis":"K2-2-u2-X02"}],"explanation":["좋은 점을 말해 줘요.","48쪽 그림 나예요.","기분 좋게 대답해요."],"asset":{"type":"passage","lines":["가: 「국어 시간에 내가 발표할게.」 「좋아. 이번에는 네가 하고 다음에는 내가 할게.」","나: 「내가 만든 것 어때?」 「우아! 정말 멋지다. 나도 너처럼 잘 만들고 싶어.」","다: 「생일 축하한다.」 「제 생일을 축하해 주셔서 고맙습니다.」"],"title":"『국어』 48쪽 그림 가~다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#11','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C1',2,'match','auto','『국어』 43쪽 — 먼저 한 말과 대답하는 고운 말을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u2-C1","difficulty":2,"kind":"match","stem":"『국어』 43쪽 — 먼저 한 말과 대답하는 고운 말을 이어 보세요.","pairs":[{"l":"상 받았구나. 축하해!","r":"네가 축하해 주니 기분이 좋아."},{"l":"어디 아프니?","r":"감기에 걸린 것 같아. 걱정해 줘서 고마워."},{"l":"실수로 네 물건을 떨어뜨려서 미안해.","r":"괜찮아. 일부러 그런 것 아니잖아."}],"mis":"K2-2-u2-X01","explanation":["고운 말에는 고운 말로 대답해요.","43쪽이에요.","상황에 알맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#12','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C8',2,'ox','auto','대화할 때에는 말뿐 아니라 표정과 말투로도 반응해요.',ARRAY['K2-2-u2-X14']::text[],false,'{"seq":12,"concept":"K2-2-u2-C8","difficulty":2,"kind":"ox","stem":"대화할 때에는 말뿐 아니라 표정과 말투로도 반응해요.","answer":"O","reason_options":[{"t":"표정, 목소리, 행동이 대화 상황에 어울려야 하니까","correct":true},{"t":"표정은 사진 찍을 때만 중요하니까","mis":"K2-2-u2-X14"}],"mis":"K2-2-u2-X14","explanation":["표정과 말투도 반응이에요.","62쪽 도움말이에요.","상황에 알맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#13','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C6',2,'mc','auto','지도서 121쪽 「현명한 칭찬」 — 바르게 칭찬한 말은?',ARRAY['K2-2-u2-X10']::text[],false,'{"seq":13,"concept":"K2-2-u2-C6","difficulty":2,"kind":"mc","stem":"지도서 121쪽 「현명한 칭찬」 — 바르게 칭찬한 말은?","options":[{"t":"날마다 끝까지 포기하지 않고 연습한 네가 정말 멋져.","correct":true},{"t":"1등 했으니까 네가 최고야.","mis":"K2-2-u2-X10"},{"t":"상 받으면 선물 줄게.","mis":"K2-2-u2-X10"}],"explanation":["과정을 칭찬했어요.","지도서 121쪽이에요.","노력을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#14','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C7',2,'mc','auto','「나도 너처럼 줄넘기를 잘하고 싶은데…….」에 바르게 조언한 말은?',ARRAY['K2-2-u2-X12','K2-2-u2-X11']::text[],false,'{"seq":14,"concept":"K2-2-u2-C7","difficulty":2,"kind":"mc","stem":"「나도 너처럼 줄넘기를 잘하고 싶은데…….」에 바르게 조언한 말은?","options":[{"t":"날마다 10분씩 줄넘기 연습을 해 보면 어떨까?","correct":true},{"t":"그냥 하면 돼.","mis":"K2-2-u2-X12"},{"t":"너는 왜 그렇게 못하니?","mis":"K2-2-u2-X11"}],"explanation":["방법을 알려 주었어요.","56쪽이에요.","부드럽게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
