INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#20','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C7',3,'mc','auto','『국어』 67쪽 — 「아, 힘들어. 좀 쉬었다 해야겠다.」 하는 친구에게 「야! 친구들이 청소하는 것 안 보이니?」 대신 할 말은?',ARRAY['K2-2-u2-X11','K2-2-u2-X13']::text[],false,'{"seq":20,"concept":"K2-2-u2-C7","difficulty":3,"kind":"mc","stem":"『국어』 67쪽 — 「아, 힘들어. 좀 쉬었다 해야겠다.」 하는 친구에게 「야! 친구들이 청소하는 것 안 보이니?」 대신 할 말은?","options":[{"t":"많이 힘들지? 조금만 더 힘내서 우리 같이 청소하자.","correct":true},{"t":"너만 쉬면 반칙이야!","mis":"K2-2-u2-X11"},{"t":"그럼 너는 하지 마.","mis":"K2-2-u2-X13"}],"explanation":["먼저 상태를 살펴요.","함께하자고 부드럽게 말해요.","지도서 124쪽이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"아, 힘들어. 좀 쉬었다 해야겠다."},{"who":"친구 2","text":"야! 친구들이 청소하는 것 안 보이니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#21','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C8',3,'mc','auto','「내가 키우던 식물이 시들어 버려서 너무 속상해.」에 적절하게 반응한 말은?',ARRAY['K2-2-u2-X06','K2-2-u2-X14']::text[],false,'{"seq":21,"concept":"K2-2-u2-C8","difficulty":3,"kind":"mc","stem":"「내가 키우던 식물이 시들어 버려서 너무 속상해.」에 적절하게 반응한 말은?","options":[{"t":"시들어서 속상하겠다. 선생님께 다시 자라게 하는 방법을 여쭤보면 어떨까?","correct":true},{"t":"식물은 또 사면 되잖아.","mis":"K2-2-u2-X06"},{"t":"(하품하며) 응, 그래.","mis":"K2-2-u2-X14"}],"explanation":["공감하고 방법도 말했어요.","63쪽이에요.","적절히 반응했어요."],"asset":{"type":"speech","turns":[{"who":"짝","text":"내가 키우던 식물이 시들어 버려서 너무 속상해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#22','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C8',3,'mc','auto','지도서 118쪽 — 표정이나 몸짓 같은 반응에 대해 알맞은 것은?',ARRAY['K2-2-u2-X15','K2-2-u2-X14']::text[],false,'{"seq":22,"concept":"K2-2-u2-C8","difficulty":3,"kind":"mc","stem":"지도서 118쪽 — 표정이나 몸짓 같은 반응에 대해 알맞은 것은?","options":[{"t":"많이 한다고 무조건 좋은 것이 아니라 대화 상황에 알맞게 해야 해요","correct":true},{"t":"많이 할수록 좋아요","mis":"K2-2-u2-X15"},{"t":"하지 않는 것이 좋아요","mis":"K2-2-u2-X14"}],"explanation":["상황에 알맞게요.","지도서 118쪽이에요.","지나치지 않게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#23','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C5',4,'sa','auto','「상대가 잘하는 점이나 노력하는 점, 좋은 점 등을 높이 평가해 주는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u2-C5","difficulty":4,"kind":"sa","stem":"「상대가 잘하는 점이나 노력하는 점, 좋은 점 등을 높이 평가해 주는 것」을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["칭찬"],"explanation":["칭찬이에요.","54쪽이에요.","조언과 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#24','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C4',4,'essay','teacher','『국어』 66쪽 1번 — 전학 온 친구의 마음을 생각하며, 전학 온 친구에게 할 고운 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u2-C4","difficulty":4,"kind":"essay","stem":"『국어』 66쪽 1번 — 전학 온 친구의 마음을 생각하며, 전학 온 친구에게 할 고운 말을 쓰세요.","answer_guide":{"answer":"예: 같은 반이 됐으니 앞으로 친하게 지내자. / 우리 학교에 정말 잘 왔어. 잘 지내자.","scoring_points":["전학 온 친구의 마음을 생각했어요","고운 말을 썼어요"]},"explanation":["낯선 친구의 마음을 생각해요.","반갑게 말해요.","66쪽 예시 답안이에요."],"asset":{"type":"speech","turns":[{"who":"전학 온 친구","text":"안녕? 난 전학 온 정보윤이야."},{"who":"친구","text":"만나서 반가워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u2_review_d#25','kor',2,2,'u2','','g2_2_kor_u2_review_d','unit_review','K2-2-u2-C8',4,'essay','teacher','친구가 「발표할 때마다 떨려서 목소리가 작아져.」라고 해요. 적절히 반응하며 조언하는 말을 쓰고, 그때 지을 표정이나 말투도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u2-C8","difficulty":4,"kind":"essay","stem":"친구가 「발표할 때마다 떨려서 목소리가 작아져.」라고 해요. 적절히 반응하며 조언하는 말을 쓰고, 그때 지을 표정이나 말투도 쓰세요.","answer_guide":{"answer":"예: (걱정하는 표정으로 부드럽게) 발표할 때 떨려서 속상했구나. 집에서 거울을 보고 연습해 보면 어떨까?","scoring_points":["공감하며 반응했어요","해결 방법이 있어요","표정이나 말투를 썼어요"]},"explanation":["바라보며 공감해요.","표정과 말투도 생각해요.","지도서 129쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
